// ============================================================================
// VOXERIA -- ENGINE
// ----------------------------------------------------------------------------
// Renderer, physics, overworld generation, input, audio, multiplayer, HUD and
// every other system the game needs to exist at all. Loaded FIRST by index.html.
//
// This file is shared ground. Dimension/progression work belongs in
// voxeria-dimensions-progress.js; mod-system work belongs in voxeria-modding.js.
// Both load after this one and can freely call anything declared here, because
// every game script is a classic (non-module) script and they therefore all
// share one global scope -- exactly as they did when this was a single file.
// ============================================================================

  // =========================================================
  // STANDALONE-INITIALISIERUNG (itch.io-Build, kein Platform-SDK)
  // =========================================================
  // loadProgressFromCloud() touches state (_progressRestoreAttempted) that's
  // declared with `let` much further down this file. Calling it here during
  // initial parse would hit those in their temporal dead zone. The platform
  // SDK used to defer this via its async init(); with the SDK gone we defer
  // it to DOMContentLoaded, which fires only after the whole script (and all
  // those declarations) has executed.
  (function _bootStandaloneProgress() {
    function run() { try { loadProgressFromCloud(); } catch (e) { console.error("loadProgressFromCloud error:", e); } }
    if (document.readyState === 'loading') {
      window.addEventListener('DOMContentLoaded', run);
    } else {
      run();
    }
  })();

  // No platform account system in the standalone build — players always fall
  // back to the generic label; multiplayer identity still works via the
  // world/room seed itself.
  window._playerDisplayName = null;

  window._activeModCode = null;

  // =========================================================
  // TAB-WECHSEL SCHUTZ
  // =========================================================
  // The mute button itself was removed; window.isGameMuted/_effectiveMuted()
  // stay because they're still read by the tab-visibility pause/resume logic
  // and initAudio() below — isGameMuted just now permanently stays false
  // since nothing sets it to true anymore.
  window.isGameMuted = false;

  function _effectiveMuted() { return !!window.isGameMuted; }

  // =========================================================
  // SETTINGS POPOVER — master volume slider + rebindable movement keys.
  // Volume persists via getMasterVolume/setMasterVolume (see masterGain
  // near audioCtx). Keybinds persist via keyBinds/saveKeyBinds (see
  // DEFAULT_KEYBINDS near `const keys = {}`).
  // =========================================================
  function toggleGameMenu(force) {
    const panel = document.getElementById('game-menu-panel');
    const btn = document.getElementById('game-menu-btn');
    if (!panel || !btn) return;
    const willOpen = typeof force === 'boolean' ? force : !panel.classList.contains('open');
    panel.classList.toggle('open', willOpen);
    btn.classList.toggle('open', willOpen);
    // Abschnitte ohne sichtbare Eintraege ausblenden. Muss beim OEFFNEN
    // laufen: die Pruefung misst die tatsaechliche Sichtbarkeit, und die ist
    // erst ablesbar, wenn das Panel selbst offen ist.
    if (willOpen && typeof window.vxHideEmptyMenuSections === 'function') window.vxHideEmptyMenuSections();
  }
  // The game loop checks this every frame to freeze simulation while the
  // pause menu is open (see the `paused` guard in _gameLoopInner).
  function isGamePaused() {
    const panel = document.getElementById('game-menu-panel');
    return !!panel && panel.classList.contains('open');
  }
  let _rebindListening = null; // action name currently waiting for a keypress, or null
  function toggleSettingsPopover() {
    const pop = document.getElementById('settings-popover');
    if (!pop) return;
    const willOpen = !pop.classList.contains('open');
    pop.classList.toggle('open', willOpen);
    if (willOpen) renderSettingsPopover();
    else _cancelRebind();
  }
  function renderSettingsPopover() {
    const slider = document.getElementById('volume-slider');
    if (slider) { slider.value = Math.round(getMasterVolume() * 100); _updateVolumeReadout(slider.value); }
    ['left', 'right', 'jump'].forEach(action => {
      const btn = document.getElementById('rebind-' + action);
      if (btn) btn.textContent = keyLabel(keyBinds[action]);
    });
  }
  // Keeps both the "72%" label and the slider's own filled-track colour (a
  // CSS custom property the track gradient reads, since a plain <input
  // type=range> has no native concept of "how much of the rail is filled")
  // in sync with the current value — called on drag and on popover open.
  function _updateVolumeReadout(val) {
    const pct = Math.round(val);
    const readout = document.getElementById('volume-readout');
    if (readout) readout.textContent = pct + '%';
    const slider = document.getElementById('volume-slider');
    if (slider) slider.style.setProperty('--vv-fill', pct + '%');
  }
  function _cancelRebind() {
    if (!_rebindListening) return;
    const btn = document.getElementById('rebind-' + _rebindListening);
    if (btn) btn.classList.remove('listening');
    _rebindListening = null;
  }
  function startRebind(action) {
    _cancelRebind();
    _rebindListening = action;
    const btn = document.getElementById('rebind-' + action);
    if (btn) { btn.classList.add('listening'); btn.textContent = 'Press a key…'; }
  }
  function resetKeyBinds() {
    keyBinds = { ...DEFAULT_KEYBINDS };
    saveKeyBinds();
    renderSettingsPopover();
    showNotification('⌨️ Controls reset to default.');
  }
  // Captures the next keypress while a rebind button is "listening" — runs
  // before the main keydown handler so the captured key never also moves the
  // player or opens chat/inventory the same frame it's bound.
  document.addEventListener('keydown', function(e) {
    if (!_rebindListening) return;
    e.preventDefault(); e.stopPropagation();
    const k = e.key.toLowerCase();
    if (k === 'escape') { _cancelRebind(); renderSettingsPopover(); return; }
    // Digits stay reserved for hotbar slot selection — refuse to shadow them.
    if (/^[0-9]$/.test(k)) { showNotification('⌨️ That key is reserved for the hotbar.'); return; }
    keyBinds[_rebindListening] = k;
    saveKeyBinds();
    _rebindListening = null;
    renderSettingsPopover();
  }, true);

  // Tab im Hintergrund -> Ton pausieren. Tab wieder sichtbar -> Ton nur
  // fortsetzen, wenn nicht effektiv gemutet.
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      if (window._vAudio) { try { window._vAudio.suspend().catch(() => {}); } catch (e) {} }
    } else {
      if (window._vAudio && !_effectiveMuted()) { try { window._vAudio.resume().catch(() => {}); } catch (e) {} }
    }
  });

  // =========================================================
  // FIREBASE LOADER
  // =========================================================
  window.firebaseReady = import("https://www.gstatic.com/firebasejs/11.6.1/firebase-app.js")
  .then(appMod => Promise.all([
    Promise.resolve(appMod),
    import("https://www.gstatic.com/firebasejs/11.6.1/firebase-auth.js"),
    import("https://www.gstatic.com/firebasejs/11.6.1/firebase-firestore.js")
  ]))
  .then(([appMod, authMod, storeMod]) => ({
    initializeApp: appMod.initializeApp,
    getAuth: authMod.getAuth,
    signInAnonymously: authMod.signInAnonymously,
    signInWithCustomToken: authMod.signInWithCustomToken,
    onAuthStateChanged: authMod.onAuthStateChanged,
    getFirestore: storeMod.getFirestore,
    initializeFirestore: storeMod.initializeFirestore,
    collection: storeMod.collection,
    doc: storeMod.doc,
    setDoc: storeMod.setDoc,
    deleteDoc: storeMod.deleteDoc,
    onSnapshot: storeMod.onSnapshot,
    getDocs: storeMod.getDocs,
    // Single-document read. Rooms are stored at a deterministic id, so joining
    // one is a `get`, not a search. See _lookupRoom() for why that difference
    // is the whole reason joining used to fail.
    getDoc: storeMod.getDoc,
    query: storeMod.query,
    where: storeMod.where,
    orderBy: storeMod.orderBy,
    limitQuery: storeMod.limit,
    increment: storeMod.increment
  }));


// =========================================================
// FIREBASE MULTIPLAYER
// =========================================================
let initializeApp, getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged, getFirestore, initializeFirestore, collection, doc, setDoc, deleteDoc, onSnapshot, getDocs, getDoc, query, where, orderBy, limitQuery, increment;
let db, auth, userId, appId;
let isMultiplayerActive = false;
let otherPlayers = {};
// Every online player's seed, INCLUDING the ones filtered out of otherPlayers
// for being in a different world. cleanupAbandonedSeed is the only consumer:
// it must not wipe a world someone else is still standing in.
let _seedPresence = {};
let _worldUnsub = null;

// Real Firebase project credentials (Firebase Console -> Project Settings -> General -> Your apps -> SDK setup and configuration).
// If this ever needs to point at a different Firebase project, initFirebase() below falls back to "Offline (Local)"
// gracefully as long as apiKey is empty/placeholder, so multiplayer degrades safely instead of throwing.
// === ITCH.IO DEPLOYMENT CHECKLIST ===
// 1) Authorized Domains:   Firebase Console -> Authentication -> Settings -> Authorized domains
//    -> "itch.io" und "itch.zone" eintragen, sonst schlaegt signInAnonymously fehl.
// 2) API-Key Restrictions: Falls in Google Cloud Console -> APIs & Services -> Credentials
//    HTTP-Referrer-Beschraenkungen aktiv sind -> dieselben itch.io-Domains dort freigeben.
// 3) Sandbox-Iframe:       itch.io laedt Spiele ebenfalls in einem Iframe; externe Netzwerk-
//    Calls (wie diese Firebase-Requests) sind davon nicht betroffen und funktionieren normal.
// 4) Firestore Rules:      Die Security Rules pruefen nur request.auth, nicht die Domain -
//    keine Anpassung dort noetig, nur die beiden Punkte oben.
const firebaseConfig = {
    apiKey: "AIzaSyAZzGkkqTyRxbJDehI-gtsNjf6IcgAPZoY",
    authDomain: "voxeria-1e357.firebaseapp.com",
    projectId: "voxeria-1e357",
    storageBucket: "voxeria-1e357.firebasestorage.app",
    messagingSenderId: "361199903585",
    appId: "1:361199903585:web:50c05d50e9eae3b1c25b20"
};

async function initFirebase() {
    try {
        ({ initializeApp, getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged, getFirestore, initializeFirestore, collection, doc, setDoc, deleteDoc, onSnapshot, getDocs, getDoc, query, where, orderBy, limitQuery, increment } = await window.firebaseReady);
        appId = typeof __app_id !== 'undefined' ? __app_id : (firebaseConfig.projectId || 'voxeria-multiplayer-app');
        if (!firebaseConfig.apiKey || firebaseConfig.apiKey.startsWith('PASTE_YOUR_')) {
            document.getElementById('mp-status').innerText = "Offline (Local)";
            console.warn("Voxeria: firebaseConfig still contains placeholder values - multiplayer disabled. Fill in real Firebase credentials to enable it.");
            return;
        }
        const app = initializeApp(firebaseConfig);
        auth = getAuth(app);
        // itch.io laedt das Spiel in einem Iframe, in dem Firestores Standard-Streaming-
        // Verbindung (WebChannel) unter Umstaenden lautlos haengen bleibt (kein Fehler, keine
        // Antwort). Long-Polling funktioniert auch durch solche restriktiven Proxies hindurch.
        try {
            db = initializeFirestore(app, { experimentalAutoDetectLongPolling: true, useFetchStreams: false });
        } catch (e) {
            console.warn("initializeFirestore mit Long-Polling fehlgeschlagen, falle auf getFirestore zurueck:", e);
            db = getFirestore(app);
        }
        if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
            await signInWithCustomToken(auth, __initial_auth_token);
        } else {
            await signInAnonymously(auth); // benoetigt Authorized Domain + ggf. API-Key-Freigabe, siehe oben
        }
        onAuthStateChanged(auth, (user) => {
            if (user) {
                userId = user.uid;
                isMultiplayerActive = true;
                document.getElementById('mp-status').style.color = "#00ffaa";
                startMultiplayerSync();
                _updateRoomState();
            }
        });
    } catch (e) {
        console.error("Firebase error:", e);
        document.getElementById('mp-status').innerText = "Offline (Error)";
        document.getElementById('mp-status').style.color = "#ff5555";
    }
}

function subscribeWorldSync() {
    if (!db) return;
    if (_worldUnsub) { _worldUnsub(); _worldUnsub = null; }
    const worldRef = collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_world_' + SEED);
    _worldUnsub = onSnapshot(worldRef, (snapshot) => {
        snapshot.docChanges().forEach((change) => {
            if (change.type === "added" || change.type === "modified") {
                const data = change.doc.data();
                // Used to skip changes where data.userId === userId, meant to avoid
                // redundantly re-applying your own just-placed block. But Firestore's
                // anonymous auth keeps the same userId across reloads on the same
                // device/browser, so on a fresh load EVERY saved edit from a solo
                // session is "your own" — the filter was silently discarding a
                // returning player's entire build. localSetBlock is a plain array
                // write with no side effects, so re-applying it is harmless; just
                // always apply the incoming state instead of filtering by author.
                // Portals are never persisted in this build (see setBlockAndBroadcast),
                // so ignore any portal blocks still lingering in the shared world from
                // older sessions — they must not reappear; each player rebuilds their
                // own locally.
                if (data.type !== undefined && data.type !== BLOCKS.PORTAL) {
                    localSetBlock(data.wx, data.wy, data.type, data.dim);
                }
            }
        });
    }, (error) => console.error("Snapshot Error (World):", error));
}

// Every block edit used to persist FOREVER in its own voxeria_world_<seed>
// Firestore collection, for every seed anyone ever typed in or generated —
// with no cleanup, that's an ever-growing pile of abandoned collections for
// seeds nobody will ever revisit. This deletes an abandoned seed's world data
// when the player leaves it for a different one, UNLESS either safety check
// below says it's still needed:
//   0. It's a room somebody deliberately created (voxeria_rooms) — those must
//      survive so "Join" keeps working for everyone, forever.
//   1. Another player's client is still actively synced to that exact seed
//      (checked via the `seed` field now included in the voxeria_players
//      position-sync payload) — guards the transition window right after a
//      shared multiplayer seed change, where other clients haven't caught up
//      to the new seed yet and are still reading/writing the old one.
// Fire-and-forget: never awaited by callers, and never blocks switching to
// the new seed — deleting old data is best-effort cleanup, not something the
// player should ever wait on or have block them.
async function cleanupAbandonedSeed(oldSeed) {
  try {
    if (!oldSeed || !db || !appId) return;
    if (oldSeed === rawSeedString) return; // didn't actually change

    // Safety check 0: is this a room somebody deliberately created? Rooms are
    // meant to be come-back-to-able, so their world outlives every player
    // logging off — unlike a seed someone typed once to peek at the terrain,
    // which is still cleaned up below.
    const roomQ = query(collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_rooms'), where('seed', '==', oldSeed));
    const roomSnap = await getDocs(roomQ);
    if (!roomSnap.empty) return;

    // Safety check 1: is anyone else's client still actively on that seed?
    // Reads _seedPresence, not otherPlayers — otherPlayers only ever holds
    // players in OUR world now, which is exactly the set that can't answer
    // this question. 8s matches drawOtherPlayers' staleness cutoff.
    const now = Date.now();
    for (const id in _seedPresence) {
      const p = _seedPresence[id];
      if (p.seed === oldSeed && (now - (p.ts || 0)) < 8000) return;
    }

    const worldRef = collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_world_' + seedToNumber(oldSeed));
    const snap = await getDocs(worldRef);
    if (snap.empty) return;
    await Promise.all(snap.docs.map(d => deleteDoc(d.ref).catch(() => {})));
  } catch (e) {
    console.warn('cleanupAbandonedSeed error (non-fatal):', e);
  }
}

// There used to be a global `voxeria_state/current` document holding ONE seed
// for everybody, which every client followed via onSnapshot. That made any
// player typing a seed teleport every other player on the planet into their
// world mid-game — a private experiment silently hijacked everyone's session.
// The seed IS the room now: you simply meet whoever else is on the same seed
// (see the seed filter below), and nothing is ever pushed onto anyone.
// The weekly world still converges without a shared document, because every
// client derives it from the same clock via getWeeklySeedString() and rolls
// over on its own timer (see updateWeeklyCountdown's setInterval).
function startMultiplayerSync() {
    if (!userId || !db) return;
    const playersRef = collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_players');
    onSnapshot(playersRef, (snapshot) => {
        snapshot.docChanges().forEach((change) => {
            if (change.doc.id === userId) return;
            if (typeof _bannedUids !== 'undefined' && _bannedUids[change.doc.id] && _bannedUids[change.doc.id].type !== 'mute') { delete otherPlayers[change.doc.id]; delete _seedPresence[change.doc.id]; return; }
            if (change.type === "added" || change.type === "modified") {
                const data = change.doc.data();
                // Tracked for EVERY online player regardless of seed, because
                // cleanupAbandonedSeed needs to know whether anyone is still on
                // the world we're leaving — and the filter right below is about
                // to drop exactly those foreign-seed players from otherPlayers.
                _seedPresence[change.doc.id] = { seed: data.seed, ts: data.ts || 0 };
                // The seed is the room: only players in the same world are ours
                // to render or interact with.
                if (data.seed !== rawSeedString) { delete otherPlayers[change.doc.id]; return; }
                // Network updates only arrive ~10x/sec; keep the last rendered position
                // around so drawOtherPlayers() can glide toward the new one instead of
                // snapping, same idea as the camera's existing smoothing.
                const prev = otherPlayers[change.doc.id];
                data.renderX = prev ? prev.renderX : data.x;
                data.renderY = prev ? prev.renderY : data.y;
                if (prev) { data._lastRenderX = prev._lastRenderX; data._lastBr = prev._lastBr; }
                otherPlayers[change.doc.id] = data;
            }
            if (change.type === "removed") { delete otherPlayers[change.doc.id]; delete _seedPresence[change.doc.id]; }
        });
        _updateRoomState();
    }, (error) => console.error("Snapshot Error (Players):", error));
    subscribeWorldSync();
    subscribePocketRuns();
}

// =========================================================
// ROOMS — the seed IS the room
// =========================================================
// A "room" is just a seed somebody deliberately claimed, recorded in the
// voxeria_rooms collection. The only thing that registration buys is
// permanence: cleanupAbandonedSeed refuses to wipe a registered world, while
// a seed you merely typed in to look around still gets collected. Joining is
// nothing more than switching to that seed — there is no host, no session and
// nothing that can be pushed onto another player.
const ROOM_PREFIX = 'VOX-';
let _roomMeta = null;      // registry doc for the current seed, or null
let _roomMetaSeed = null;  // which seed _roomMeta was looked up for
let _lastRoomTouch = 0;
let _roomPanelOpen = false;
// Opt-out of being seen and of seeing others. Persisted, defaults to on so
// nothing changes for existing players.
let mpVisible = localStorage.getItem('voxeria_mp_visible') !== '0';

function roomDocRef(seed) {
  return doc(db, 'artifacts', appId, 'public', 'data', 'voxeria_rooms', String(seedToNumber(seed)));
}

function isRoomCode(s) { return typeof s === 'string' && s.toUpperCase().startsWith(ROOM_PREFIX); }

// Counts only players sharing our world — otherPlayers is already seed-scoped,
// this just drops the ones who went quiet without their doc being removed.
function countPlayersHere() {
  const now = Date.now();
  let n = 0;
  for (const id in otherPlayers) if (now - (otherPlayers[id].ts || 0) < 8000) n++;
  return n;
}

function _updateRoomState() {
  const el = document.getElementById('mp-status');
  if (el && isMultiplayerActive) {
    const n = countPlayersHere() + 1;
    const label = isRoomCode(rawSeedString) ? rawSeedString
                : isWeeklyAutoSeed(rawSeedString) ? 'Lobby'
                : 'Seed';
    el.textContent = mpVisible ? `👥 ${label} · ${n}` : '👤 Solo';
  }
  if (_roomPanelOpen) renderRoomPanel();

  if (!isMultiplayerActive || !db || !userId) return;
  // Look the registry entry up once per seed, not once per call.
  if (_roomMetaSeed !== rawSeedString) {
    _roomMetaSeed = rawSeedString;
    _roomMeta = null;
    const seedAtLookup = rawSeedString;
    getDocs(query(collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_rooms'), where('seed', '==', seedAtLookup)))
      .then(snap => {
        if (rawSeedString !== seedAtLookup) return; // player already moved on
        _roomMeta = snap.empty ? null : snap.docs[0].data();
        if (_roomPanelOpen) renderRoomPanel();
      })
      .catch(() => {});
  }
  // Keeps a room looking alive in the registry without turning _updateRoomState
  // — which fires on every players snapshot — into a write storm.
  const now = Date.now();
  if (_roomMeta && now - _lastRoomTouch > 60000) {
    _lastRoomTouch = now;
    setDoc(roomDocRef(rawSeedString), Object.assign({}, _roomMeta, { lastSeen: now })).catch(() => {});
  }
}
window._updateRoomState = _updateRoomState;

function toggleRoomPanel(force) {
  const el = document.getElementById('room-panel');
  if (!el) return;
  _roomPanelOpen = (force === undefined) ? !_roomPanelOpen : !!force;
  el.classList.toggle('open', _roomPanelOpen);
  if (_roomPanelOpen) renderRoomPanel();
}
window.toggleRoomPanel = toggleRoomPanel;

function renderRoomPanel() {
  const nameEl = document.getElementById('rp-current-name');
  const subEl = document.getElementById('rp-current-sub');
  const toggleEl = document.getElementById('rp-visible-toggle');
  if (toggleEl) toggleEl.checked = mpVisible;
  if (!nameEl || !subEl) return;
  if (!isMultiplayerActive) {
    nameEl.textContent = 'Offline';
    subEl.textContent = 'No connection, so you are playing solo.';
    return;
  }
  if (_roomMeta) nameEl.textContent = _roomMeta.name || rawSeedString;
  else if (isWeeklyAutoSeed(rawSeedString)) nameEl.textContent = "This week's public world";
  else nameEl.textContent = rawSeedString;
  const n = countPlayersHere();
  const who = n === 0 ? 'You are the only one here' : n === 1 ? '1 other player here' : n + ' other players here';
  subEl.textContent = `${who} · ${_roomMeta ? 'saved room' : 'temporary world'}`;
}

function joinWeeklyLobby() {
  const input = document.getElementById('seed-input');
  if (input) input.value = getWeeklySeedString();
  applySeedFromUI();
  showNotification('🌍 Joined the public world');
  renderRoomPanel();
}
window.joinWeeklyLobby = joinWeeklyLobby;

// mode/arenaWidth kommen aus dem Host-Bildschirm (siehe VxWorlds.confirmHostRoom)
// und reisen im Raum-Eintrag mit, damit jeder Beitretende DIESELBE Weltart und
// -breite erzeugt. Ohne sie stuende der Gastgeber in einer leeren Arena,
// waehrend der Gast normales Terrain generiert -- beide auf demselben Seed,
// beide ueberzeugt, im selben Raum zu sein.
// A room is NOT a named save: it appears in no world list, and its world lives
// in Firestore rather than localStorage. Leaving `currentWorldId` pointing at
// the world you came from is not merely untidy: VxWorlds' 20-second autosave
// then writes the ROOM seed and the blocks built in the room into that private
// world's record. The next "Load World" opens somebody else's terrain under
// your own world name, and the original world is gone.
//
// So the world being left is saved once more and then deliberately released,
// in TWO steps, because the two belong at different moments:
//
//   _flushWorldBeforeLeaving()  at the very start, BEFORE any change to
//                               gameMode or the arena width. VxWorlds'
//                               serialize() reads exactly those two; saving
//                               after the room's mode has been set stamps the
//                               room's mode (and, for arena, its width) into
//                               the private save.
//   _leaveNamedWorldForRoom()   immediately before the seed switch.
function _flushWorldBeforeLeaving() {
  if (currentWorldId && window.VxWorlds && typeof VxWorlds.save === 'function') {
    try { VxWorlds.save(); } catch (e) { console.warn('Voxeria: could not flush the world being left', e); }
  }
}
window._flushWorldBeforeLeaving = _flushWorldBeforeLeaving;

function _leaveNamedWorldForRoom() {
  currentWorldId = null;
  currentWorldName = null;
}

// Creates a room. ASYNC and with a return value, because creating one really
// can fail (rules, network, an expired sign-in). The `setDoc` used to run
// fire-and-forget with nothing but a console.error, so the host was shown
// "Room created" in EVERY case. The room was then in no registry, the host
// switched to the seed anyway, and the friend typing the code in found simply
// nothing. That is precisely the "Host Room does not work at all" this fixes.
//
// Returns: the room code on success, otherwise null. The caller decides for
// itself whether to close its screen.
async function createRoom(mode, arenaWidth) {
  if (!isMultiplayerActive || !db || !userId) { showNotification('⚠️ Multiplayer is offline'); return null; }
  // Harmlessly redundant: confirmHostRoom() already saves before it switches
  // the mode. This call covers the other route, the button in the multiplayer
  // panel, which never goes through a menu screen.
  _flushWorldBeforeLeaving();
  let code = ROOM_PREFIX;
  for (let i = 0; i < 6; i++) code += 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)];
  const meta = { seed: code, seedNumber: seedToNumber(code), name: 'Room ' + code.slice(ROOM_PREFIX.length), ownerUid: userId, createdAt: Date.now(), lastSeen: Date.now(),
                 mode: mode || 'explore', arenaWidth: arenaWidth || 0 };
  // Registered BEFORE the seed switch, because applySeedFromUI immediately
  // hands the seed we're leaving to cleanupAbandonedSeed — and that runs the
  // registry check on the OLD seed while this new doc must already exist for
  // the room we're entering. Awaiting keeps that order and additionally makes
  // a failed write stop the whole thing instead of half-entering a room that
  // nobody else will ever be able to find.
  try {
    await setDoc(roomDocRef(code), meta);
  } catch (e) {
    console.error('Room create error:', e);
    showNotification('⚠️ The room could not be registered. You are still in your own world.');
    return null;
  }
  // Set mode and width LOCALLY too, not only into the room document, and do it
  // BEFORE applySeedFromUI(), because the world kind is fixed from the first
  // generated chunk on. Both real callers already set them beforehand, but
  // relying on that means any other caller could register a room calling
  // itself "arena" while its own host stands in ordinary terrain. That is
  // exactly the host-versus-joiner divergence the room document exists to
  // prevent. Setting it twice costs nothing; drifting apart is now impossible.
  if (meta.mode && window.VxWorlds && VxWorlds.MODES[meta.mode]) gameMode = meta.mode;
  if (window.VxArena) VxArena.setWorldWidth(gameMode === 'arena' ? (meta.arenaWidth || 128) : 0);
  _leaveNamedWorldForRoom();
  _roomMeta = meta; _roomMetaSeed = code; _lastRoomTouch = Date.now();
  const input = document.getElementById('seed-input');
  if (input) input.value = code;
  applySeedFromUI();
  _roomMeta = meta; _roomMetaSeed = code; // applySeedFromUI's _updateRoomState re-queries; keep the local truth
  if (window.VxWorlds && typeof VxWorlds.applyModeGating === 'function') VxWorlds.applyModeGating();
  showNotification('✨ Room created: ' + code + '. Share that code to let friends in.');
  renderRoomPanel();
  return code;
}
window.createRoom = createRoom;

// The registry entry for a room code.
//
// A direct document read FIRST: createRoom() writes the entry under a
// COMPUTABLE id (seedToNumber of the code), so there is nothing to search for.
// More importantly, a `get` is the only form that works under Firestore rules
// which grant `get` but not `list`. That is exactly where joining used to fail
// silently: the collection query threw, the catch swallowed it, and the guest
// ended up in a plain seed join, in a world that carried the same code but had
// neither the host's mode nor width, and in which they were alone.
//
// The query stays as a second attempt: rooms from before the id scheme sit
// under a different document id but carry their code in the `seed` field.
async function _lookupRoom(clean) {
  if (typeof getDoc === 'function') {
    try {
      const snap = await getDoc(roomDocRef(clean));
      if (snap.exists()) {
        const data = snap.data();
        // The id is a hash of the code; two different codes could in principle
        // produce the same number. The code inside the document decides, not
        // the id it happened to be filed under.
        if (String(data.seed || '').toUpperCase() === clean) return data;
      }
    } catch (e) {
      console.warn('Voxeria: direct room read failed, falling back to a query:', e);
    }
  }
  const snap = await getDocs(query(
    collection(db, 'artifacts', appId, 'public', 'data', 'voxeria_rooms'),
    where('seed', '==', clean)));
  return snap.empty ? null : snap.docs[0].data();
}

// Einem Raum beitreten. Der Ablauf ist bewusst ASYNCHRON und die Reihenfolge
// ist das Entscheidende daran:
//
//   1. Raum-Eintrag lesen
//   2. Modus + Arena-Breite setzen, Modus-Gating anwenden
//   3. ERST DANN den Seed anwenden
//
// Grund: applySeedFromUI() ruft resetGameAndWorld(), das ruft getChunk(), und
// ab dem allerersten erzeugten Chunk steht die Weltart fest. Wuerde der Modus
// danach gesetzt, haette der Gast bereits normales Terrain erzeugt, das durch
// keinen spaeteren Moduswechsel mehr verschwindet.
//
// Kein Eintrag gefunden -> wie bisher ein schlichter Seed-Beitritt. Das deckt
// alte Raeume ohne die neuen Felder mit ab.
// Wartet begrenzt darauf, dass Firebase angemeldet ist. Gebraucht wird das vom
// ?room=-Einladungslink: der laeuft in DOMContentLoaded los, waehrend
// initFirebase() noch mitten in seiner asynchronen Anmeldung steckt -- `db`
// ist dort schlicht noch null. Ohne dieses Warten uebersprang der Beitritt die
// Raum-Abfrage und der eingeladene Freund landete in der falschen Weltart.
//
// Begrenzt, nicht unendlich: kommt keine Verbindung zustande, soll der Link
// trotzdem etwas tun (schlichter Seed-Beitritt) statt ewig haengen zu bleiben.
function waitForDb(maxMs) {
  if (db && userId) return Promise.resolve(true);
  const started = Date.now();
  return new Promise(resolve => {
    const iv = setInterval(() => {
      if (db && userId) { clearInterval(iv); resolve(true); }
      else if (Date.now() - started > maxMs) { clearInterval(iv); resolve(false); }
    }, 120);
  });
}

// Returns a result object instead of silently doing something:
//   { ok: true,  meta }               in
//   { ok: false, reason, message }    not in, and WHY
//
// That return value is the heart of this rework. Every join used to end in
// `applySeedFromUI()` and a "Joined <code>" notification: on a typo, with no
// network, and even when the room had never existed. The player then landed
// alone in a freshly generated world that looked exactly like a room nobody
// happens to be in right now. A join that fails has to say so and leave the
// screen open.
//
// `opts.allowUnregistered` is exclusively for the ?room= invite link: its value
// comes from copyRoomInvite(), which inserts the CURRENT seed, and that need
// not be a room code. A plain seed join is the right behaviour there, and
// nowhere else.
async function joinRoomByCode(code, opts) {
  const allowUnregistered = !!(opts && opts.allowUnregistered);
  const clean = String(code || '').trim().toUpperCase();
  if (!clean) return { ok: false, reason: 'empty', message: 'Enter a room code first.' };
  if (!allowUnregistered && !isRoomCode(clean)) {
    return { ok: false, reason: 'format',
             message: 'Room codes look like ' + ROOM_PREFIX + 'ABC123. Check the code you were given.' };
  }
  // A bounded wait for the sign-in: the invite link starts running while
  // initFirebase() is still in the middle of signInAnonymously.
  const online = await waitForDb(6000);
  if (!online || !db || !appId) {
    if (!allowUnregistered) {
      return { ok: false, reason: 'offline',
               message: 'No connection to the server, so there is no room to join right now.' };
    }
  }

  let meta = null;
  let lookupFailed = false;
  if (db && appId) {
    try { meta = await _lookupRoom(clean); }
    catch (e) { lookupFailed = true; console.warn('Voxeria: room lookup failed:', e); }
  }
  if (!meta && !allowUnregistered) {
    return lookupFailed
      ? { ok: false, reason: 'lookup', message: 'The room list could not be reached. Try again in a moment.' }
      : { ok: false, reason: 'notfound', message: 'No room called ' + clean + '. Check the code, or ask the host for a fresh one.' };
  }

  // Before the first change to gameMode / arena width; see the note there.
  _flushWorldBeforeLeaving();

  // Mode and width MUST be in place before the seed: applySeedFromUI() calls
  // resetGameAndWorld() -> getChunk(), and the world kind is fixed from the
  // first generated chunk on. A mode set afterwards would come too late for
  // terrain that already exists.
  if (meta && meta.mode && window.VxWorlds && VxWorlds.MODES[meta.mode]) gameMode = meta.mode;
  // Outside the meta branch, so the width is also right when moving from an
  // arena into an ordinary room: otherwise the new, endless world would keep
  // the bedrock walls of the old one.
  if (window.VxArena) {
    VxArena.setWorldWidth(gameMode === 'arena' ? ((meta && meta.arenaWidth) || 128) : 0);
  }
  _leaveNamedWorldForRoom();
  // Also sets body[data-vx-mode], which the HUD buttons hang off. Without it
  // the guest would keep the button bar of their previous world.
  if (window.VxWorlds) VxWorlds.applyModeGating();

  if (meta) { _roomMeta = meta; _roomMetaSeed = clean; _lastRoomTouch = Date.now(); }
  const input = document.getElementById('seed-input');
  if (input) input.value = clean;
  applySeedFromUI();
  if (meta) { _roomMeta = meta; _roomMetaSeed = clean; } // applySeedFromUI re-queries; keep the local truth
  if (window.VxWorlds && typeof VxWorlds.applyModeGating === 'function') VxWorlds.applyModeGating();
  showNotification('👥 Joined ' + ((meta && meta.name) || clean));
  renderRoomPanel();
  return { ok: true, meta: meta, code: clean };
}
window.joinRoomByCode = joinRoomByCode;

function joinRoomFromInput() {
  const field = document.getElementById('rp-join-input');
  if (!field) return;
  const code = field.value.trim().toUpperCase();
  if (!code) return;
  const btn = field.parentNode && field.parentNode.querySelector('.rp-btn');
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  joinRoomByCode(code).then(res => {
    // The field is cleared on success only. After a typo the code stays put so
    // it can be corrected rather than typed out again.
    if (res.ok) field.value = '';
    else showNotification('⚠️ ' + res.message);
  }).finally(() => {
    if (btn) { btn.disabled = false; btn.textContent = 'Join'; }
  });
}
window.joinRoomFromInput = joinRoomFromInput;

function copyRoomInvite() {
  const link = location.origin + location.pathname + '?room=' + encodeURIComponent(rawSeedString);
  navigator.clipboard.writeText(link)
    .then(() => showNotification('🔗 Invite link copied'))
    .catch(() => showNotification('🔗 ' + link));
}
window.copyRoomInvite = copyRoomInvite;

function setMultiplayerVisible(on) {
  mpVisible = !!on;
  localStorage.setItem('voxeria_mp_visible', mpVisible ? '1' : '0');
  // Stop broadcasting immediately rather than letting the doc go stale, so
  // other players see you leave right away instead of 5 seconds later.
  if (!mpVisible && db && userId) {
    deleteDoc(doc(db, 'artifacts', appId, 'public', 'data', 'voxeria_players', userId)).catch(() => {});
    otherPlayers = {};
  }
  _updateRoomState();
}
window.setMultiplayerVisible = setMultiplayerVisible;

let _voxeriaHubTargetUrl = 'https://voxeriahub.com/';
function confirmVoxeriaHub(targetUrl) {
  _voxeriaHubTargetUrl = targetUrl || 'https://voxeriahub.com/';
  const isMods = _voxeriaHubTargetUrl.indexOf('#mods') !== -1;
  document.querySelector('#voxeriahub-modal h3').textContent = isMods ? 'Create Mods on Voxeria Hub?' : 'Visit Voxeria Hub?';
  document.querySelector('#voxeriahub-modal p').innerHTML = isMods
    ? 'You are leaving the game and opening <strong>voxeriahub.com</strong> in a new tab to create and publish mods.'
    : 'You are leaving the game and opening <strong>voxeriahub.com</strong> in a new tab. You will find community seeds, leaderboards, and easy modding tools all in one place.';
  document.getElementById('voxeriahub-modal').classList.add('open');
}
function closeVoxeriaHub() {
  document.getElementById('voxeriahub-modal').classList.remove('open');
}
function openVoxeriaHub() {
  window.open(_voxeriaHubTargetUrl, '_blank', 'noopener,noreferrer');
  closeVoxeriaHub();
}

// "New World" regenerates the whole world from the typed seed — and if
// you're in the shared multiplayer world, applySeedFromUI() also pushes
// that new seed to everyone else. Destructive enough (for you and possibly
// the room) to earn a confirm step instead of firing on a single click.
function openNewWorldConfirm() {
  // Used to warn that this changes the world for everyone else too — that was
  // true back when a seed change broadcast to every connected player (see
  // voxeria-mp-overhaul memory). Now the seed IS the room: only you change
  // worlds, nobody else is affected, so the warning no longer applies.
  document.getElementById('new-world-confirm-text').textContent =
    "This discards your current world and starts a fresh one from this seed.";
  document.getElementById('new-world-confirm-modal').classList.add('open');
}
function closeNewWorldConfirm() {
  document.getElementById('new-world-confirm-modal').classList.remove('open');
}
function confirmNewWorld() {
  closeNewWorldConfirm();
  applySeedFromUI();
}
// =========================================================
// CORE CONSTANTS
// =========================================================
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Canvas text can't read CSS custom properties, so the DOM UI's --font-ui
// stack is mirrored here. Every ctx.font assignment goes through fontUI() so
// in-world text (floating damage/pickup text, item-drop counts, forge labels,
// the death screen) is the same typeface as the surrounding HUD instead of
// each call site picking its own — this file used to mix bare `sans-serif`,
// a partial `'Segoe UI', sans-serif` and even a stray `10px Arial`.
const FONT_UI_STACK = "'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
function fontUI(spec) { return spec + ' ' + FONT_UI_STACK; }
// Canvas mirror of the CSS --font-display token. Canvas can't read CSS
// variables, so the two have to be kept in step by hand — change one, change
// the other. Pass whole pixel sizes only (fontDisplay('16px')): Silkscreen is
// a bitmap design, and ctx.fillText at a fractional size anti-aliases it back
// into the soft-edged look this pass removed everywhere else.
const FONT_DISPLAY_STACK = "'Silkscreen', 'Courier New', monospace";
function fontDisplay(spec) { return spec + ' ' + FONT_DISPLAY_STACK; }

const TILE = 28;
let COLS = Math.floor(1280 / TILE); // ~45
let ROWS = Math.floor(720 / TILE);  // ~25
const WORLD_H = 120;
const CHUNK_W = 32;
const GRAVITY = 0.4;
// Master toggle for the subtle 2.5D depth shading in drawBlock() (neighbour-
// aware rims + ambient-occlusion crevice shadows). Set to false for the old
// flat look; no gameplay effect either way.
const DEPTH_SHADING = true;

// =========================================================
// FULL-BLEED CANVAS
// The canvas internal resolution (canvas.width/height) is resized to
// exactly match #canvas-wrapper's real box, instead of staying a fixed
// 1280x720 buffer that gets letterboxed (object-fit:contain) on any
// screen whose aspect ratio isn't exactly 16:9 — which, before this ran
// on desktop too, was the actual cause of the black bars: a 1280x720
// buffer stretched into a wider/taller box has to add bars somewhere to
// keep its own aspect ratio. COLS/ROWS (visible tile count) is recomputed
// to match, and the world-render loop already reads COLS/ROWS rather
// than literal numbers, so more/less of the world simply becomes
// visible — no separate "zoom" logic needed. Used to be touch-only; now
// applies to every device since the bars were never a mobile-only problem.
// =========================================================
// =========================================================
// VibrantVox — render-resolution + atmosphere engine
// =========================================================
// Two subsystems that share one frame budget: a SCALER that decides how many
// pixels the world is drawn into, and a GRADE that decides what those pixels
// end up looking like. They live together because they trade against each
// other — the grade is only affordable when the scaler has left headroom for
// it, and the scaler is told to back the grade off when it hasn't.
//
// ---- Why the scaler exists ----
// This renderer's frame cost is dominated by PER-TILE DRAW CALLS, not by
// fill-rate. drawBlock() issues roughly a dozen canvas ops for every visible
// tile (base quad, three bevel edges, the overlay stamp, AO rims, plus the
// per-material detail pass), and the number of visible tiles is exactly
// (buffer area) / TILE². That makes the size of the pixel buffer the one
// honest cost knob in the entire pipeline: halve its area and you halve the
// per-frame draw calls. It is also why a strong GPU doesn't rescue a big
// monitor here — the work is CPU-side call overhead, not shading.
//
// The catch is that the buffer is also what you SEE. CSS stretches the canvas
// element to fill its box, so a buffer smaller than the display gets upscaled:
// cheap, but soft — and downright blocky if it's nearest-neighbour filtered.
// Resolution is therefore a genuine quality/performance trade whose right
// answer depends entirely on the machine. A high-end PC should be running at
// native resolution (zero upscaling, perfectly crisp); a weak laptop needs the
// frame-time headroom far more than it needs the sharpness. The scaler owns
// that trade instead of leaving it as a hardcoded constant: it sizes the
// buffer from a quality budget, and in "auto" it calibrates that budget
// against measured frame times during the first stretch of play. The scale
// factor is uniform across width and height, so aspect ratio is always
// preserved and this never letterboxes.
//
// ---- Why the grade exists ----
// The world was authored as a flat palette: every block carries fixed colours
// that never react to anything around them. The sky, meanwhile, already knew
// the time of day — it blends through sunset into night all on its own. So at
// dusk the sky went molten orange while the grass underneath stayed exactly as
// green as it was at noon. Nothing tied the scene together, and that
// disagreement is what made the world read as flat rather than atmospheric.
//
// Fixing it per-block would mean re-tinting a hundred-odd palette entries on
// every draw call — precisely the per-tile cost the scaler exists to protect.
// So the grade runs once per frame over the FINISHED image instead: a handful
// of full-screen composite passes, whose cost depends on screen area rather
// than on how much is in the scene. Same result, a rounding error of the price:
//
//   1. Vibrance — the frame blended onto itself in 'overlay'. Deepens shadows
//      and pushes saturation along an S-curve without shifting hue.
//   2. Ambient light — a 'soft-light' wash in the colour of whatever is
//      actually lighting this place (sun, sunset, moon, lava, void). This is
//      the pass that finally makes ground and sky agree.
//   3. Bloom — bright things bleed light, the way they do through a real lens.
//
// Everything downstream of drawLightingPass() is deliberately left ungraded:
// floating damage numbers, pings and hover highlights are information, not
// scenery, and they stay crisp and readable.
const VibrantVox = (function () {
  const LS_ATMO = 'voxeria_vibrantvox_atmosphere';

  // Buffer-area ladder, in pixels. Each rung is roughly 1.25-1.35x the area of
  // the one below: small enough that a change isn't visually jarring, large
  // enough that stepping buys measurable frame time. Infinity means "native" —
  // never shrink the buffer below the display, i.e. zero upscaling at all.
  const LADDER = [
     960 *  540, // 0 — last resort on very weak hardware
    1120 *  630, // 1
    1280 *  720, // 2 — the resolution this renderer was originally tuned at
    1440 *  810, // 3
    1600 *  900, // 4 — safe default
    1920 * 1080, // 5
    2400 * 1350, // 6
    Infinity,    // 7 — native: sharpest possible output, heaviest
  ];
  const NATIVE_RUNG = LADDER.length - 1;
  const DEFAULT_RUNG = 4;

  // A buffer this small is comically zoomed-in (you'd see almost no world), so
  // it's a hard floor regardless of how badly the machine is struggling.
  const MIN_W = 480, MIN_H = 270;

  const MODES = {
    auto:        { rung: DEFAULT_RUNG, adaptive: true,  label: 'Auto' },
    sharp:       { rung: NATIVE_RUNG,  adaptive: false, label: 'Ultra' },
    balanced:    { rung: DEFAULT_RUNG, adaptive: false, label: 'Balanced' },
    performance: { rung: 1,            adaptive: false, label: 'Performance' },
  };

  const WARMUP_MS      = 2500;  // worldgen + first chunk streaming spike badly
  const SAMPLE_MS      = 1500;  // length of one measurement window
  const CALIBRATE_MS   = 25000; // after this, stop reaching for MORE quality
  const COOLDOWN_MS    = 2500;  // minimum spacing between resolution changes
  // Frames longer than this are treated as noise rather than signal (GC pause,
  // tab backgrounded, a chunk streaming in). Deliberately generous: a stricter
  // cutoff would classify the genuinely slow frames of a struggling machine as
  // outliers and throw away the very evidence the controller needs.
  const SPIKE_MS       = 500;
  // Minimum usable frames per window. Kept low, and paired with a window that
  // extends rather than resets (see below), so a collapsed frame rate is still
  // measurable instead of starving the controller into silence.
  const MIN_SAMPLES    = 6;
  const FPS_LOW        = 50;    // below target -> give back resolution
  const FPS_HIGH       = 58;    // comfortable headroom -> try for more
  const FPS_EMERGENCY  = 32;    // struggling badly, act even after calibration

  // How much of the grade to actually apply. 'rich' is the default because a
  // world that reacts to its own light is the point of this engine; the milder
  // rungs exist for players who want the raw palette back.
  const ATMO_STRENGTH = { off: 0, subtle: 0.55, rich: 1 };
  let atmosphere = 'rich';

  // Quality is locked to Performance — no player-facing control and nothing
  // to restore from localStorage (see the removed vibrantvox-mode <select>).
  const mode = 'performance';
  try {
    const savedAtmo = localStorage.getItem(LS_ATMO);
    if (savedAtmo && ATMO_STRENGTH[savedAtmo] !== undefined) atmosphere = savedAtmo;
  } catch (e) {}

  let rung = MODES[mode].rung;
  // Highest rung auto is still allowed to try. Once a step up turns out to be
  // too expensive we step back down and pull this ceiling in, so the search
  // converges instead of oscillating between two rungs forever.
  let ceiling = NATIVE_RUNG;

  let scale = 1;
  let startedAt = 0, windowStart = 0, lastChangeAt = 0;
  let prevFrame = 0, frames = 0, accum = 0, lastFps = 0;
  let wrapperEl = null;

  function budgetFor(r) { return LADDER[Math.max(0, Math.min(NATIVE_RUNG, r))]; }

  // Sizes the backing store for the current rung and re-derives everything
  // downstream of it. Returns true only if the buffer actually changed.
  function apply() {
    if (!wrapperEl) wrapperEl = document.getElementById('canvas-wrapper');
    if (!wrapperEl) return false;
    const w = Math.round(wrapperEl.clientWidth);
    const h = Math.round(wrapperEl.clientHeight);
    if (w < 50 || h < 50) return false;

    // ── Portrait phones are given a wider view of the world ──────────────
    // COLS/ROWS below are derived from the BACKING STORE, and the element is
    // then stretched to its CSS box by the browser. A backing store larger
    // than that box is therefore exactly a zoom-out: more world, drawn
    // smaller. There is no second zoom path to keep in step, which is the same
    // reasoning the COLS/ROWS comment below already relies on.
    //
    // It is needed because a portrait phone is around 390 CSS pixels wide, and
    // at TILE = 28 that is thirteen columns of world. In a side-scroller
    // thirteen columns is a corridor: there is no room to see something coming
    // before you are standing in it. Landscape and desktop are wide enough
    // already and are left alone, so this only fires where the shape of the
    // screen is what caused the problem.
    const portrait = h > w * 1.2 && w < 820;
    const view = portrait ? 1.4 : 1;
    // Applied BEFORE the budget check rather than after, so a widened view
    // still has to fit the same performance budget every other rung obeys.
    // Applying it afterwards would let portrait quietly overshoot the ladder.
    const vw = w * view, vh = h * view;
    const budget = budgetFor(rung);
    const area = vw * vh;
    const s = (budget === Infinity || area <= budget) ? 1 : Math.sqrt(budget / area);
    const bw = Math.max(MIN_W, Math.round(vw * s));
    const bh = Math.max(MIN_H, Math.round(vh * s));
    if (bw === canvas.width && bh === canvas.height) return false;

    canvas.width = bw;
    canvas.height = bh;
    scale = bw / w;
    // COLS/ROWS are how much world is visible; the render loop reads these
    // rather than literal numbers, so a resolution change simply shows more or
    // less world — there is no separate zoom path to keep in sync.
    COLS = Math.floor(bw / TILE);
    ROWS = Math.floor(bh / TILE);
    // Resizing the backing store resets EVERY ctx property to its default, so
    // anything the renderer relies on has to be re-asserted here. Smoothing is
    // wanted: the light/glow stamps are drawn scaled, and nearest-neighbour
    // would make their halos read as hard-edged squares.
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    refreshReadout();
    return true;
  }

  function step(dir, now) {
    const next = Math.max(0, Math.min(ceiling, rung + dir));
    if (next === rung) return false;
    rung = next;
    if (dir < 0) ceiling = rung; // this rung failed; don't climb back past it
    lastChangeAt = now;
    return apply();
  }

  // Called once per rendered frame. Keeps a rolling average of real frame
  // times and, in auto, nudges the rung when a full window's worth of evidence
  // says the machine has either too little or plenty of headroom.
  function frame(now) {
    const prev = prevFrame;
    prevFrame = now;
    if (!startedAt) { startedAt = now; windowStart = now; return; }
    if (!prev) return;

    const dt = now - prev;
    // Outliers (chunk generation, GC pauses, the tab being backgrounded) say
    // nothing about sustainable frame rate and would panic the controller.
    if (dt > 0 && dt < SPIKE_MS) { accum += dt; frames++; }

    if (now - windowStart < SAMPLE_MS) return;

    // A machine in real trouble delivers very few frames per window, so a flat
    // "need N samples or discard" gate would blind the controller at exactly
    // the frame rates it exists to rescue. Extend the window instead of
    // resetting it, and treat a window that stayed nearly empty even then as
    // evidence in its own right rather than as missing data.
    if (frames < MIN_SAMPLES && now - windowStart < SAMPLE_MS * 4) return;
    const starved = frames < MIN_SAMPLES;

    lastFps = frames > 0 ? 1000 / (accum / frames) : 0;
    windowStart = now; frames = 0; accum = 0;
    if (!starved) refreshReadout();

    if (!MODES[mode].adaptive) return;
    const age = now - startedAt;
    if (age < WARMUP_MS) return;
    // Resolution changes rebuild the backing store and shift how much world is
    // on screen — leave it alone until play has actually started rather than
    // resizing out from under the intro screen.
    if (typeof gameState !== 'undefined' && gameState !== 'PLAYING') return;
    if (now - lastChangeAt < COOLDOWN_MS) return;

    // Couldn't gather a normal sample in four windows' worth of wall time: the
    // frame rate has collapsed hard enough that the thin average isn't worth
    // trusting, but the collapse itself is unambiguous. Act on it.
    if (starved) { step(-1, now); return; }

    const calibrating = age < CALIBRATE_MS;
    if (lastFps < (calibrating ? FPS_LOW : FPS_EMERGENCY)) { step(-1, now); return; }
    if (calibrating && lastFps > FPS_HIGH && rung < ceiling) step(+1, now);
  }

  // =======================================================
  // GRADE — atmosphere, colour and light
  // =======================================================
  // The colour of whatever is lighting the scene right now. Not the colour of
  // the sky: the colour the sky is CASTING onto everything below it.
  const LIGHT_DAY   = [255, 232, 202]; // clean daylight, warmer amber
  const LIGHT_GOLD  = [255, 158,  72]; // low sun raking across the world
  const LIGHT_NIGHT = [125, 105, 125]; // moonlight, warmer, less icy blue

  // Each biome's own colour identity, plus how hard to push its saturation.
  // Deliberately restrained — this tints the light, it doesn't repaint blocks.
  const BIOME_MOOD = {
    FOREST: { tint: [110, 225, 225], amt: 0.10, vib: 0.16 },
    SNOW:   { tint: [175, 220, 255], amt: 0.16, vib: 0.12 },
  };
  // Pocket dimensions have no sky and no clock, so their mood is fixed and
  // considerably stronger — the grade is most of what makes them feel like
  // somewhere else rather than the overworld with different blocks.
  const DIM_MOOD = {
    GOLD:  { tint: [255, 190,  60], amt: 0.22, vib: 0.24, bloom: 0.60 },
    OCEAN: { tint: [ 40, 145, 225], amt: 0.30, vib: 0.18, bloom: 0.35 },
    LAVA:  { tint: [255,  92,  28], amt: 0.26, vib: 0.26, bloom: 0.65 },
    VOID:  { tint: [155,  92, 255], amt: 0.25, vib: 0.24, bloom: 0.55 },
    ERG:   { tint: [235, 195, 110], amt: 0.20, vib: 0.16, bloom: 0.30 },
  };
  const CAVE_TINT = [70, 95, 150]; // cold, close, no sky above you

  // Bloom is blurred by downscaling and letting the smoothing filter spread it
  // on the way back up, so the divisor IS the glow radius: one source pixel
  // becomes BLOOM_DIV screen pixels of falloff. At 1/6 the light bled barely
  // 6px and read as a faint rim rather than a glow. 1/18 reaches far enough to
  // look like light in air.
  // (Widening it by compositing the buffer a second time, enlarged, would be
  // wrong: scaling the whole buffer pushes every bright spot radially away from
  // screen centre instead of spreading it in place. A smaller buffer blurs
  // where the light actually is.)
  const BLOOM_DIV = 18;
  // A single level gives a hard linear ramp exactly BLOOM_DIV wide and then
  // nothing — light doesn't stop like that. A second, much coarser level
  // composited underneath supplies the long faint tail, which is the same
  // progressive-upsample trick real bloom implementations use.
  const BLOOM_WIDE_DIV = 54;
  const BLOOM_MIN_RUNG = 3; // below this the scaler is already fighting; don't add cost
  let bloomCv = null, bloomCx = null, bloomMid = null, bloomMidCx = null,
      bloomWide = null, bloomWideCx = null;

  // Resolves everything that should influence the picture this frame into a
  // single tint / vibrance / bloom triple.
  function currentMood() {
    if (currentDim !== 'OVERWORLD') {
      const m = DIM_MOOD[currentDim];
      if (!m) return null;
      return { tint: m.tint.slice(), amt: m.amt, vib: m.vib, bloom: m.bloom, desat: 0 };
    }

    const bm = BIOME_MOOD[getBiome(Math.floor(player.x / (CHUNK_W * TILE)))] || BIOME_MOOD.FOREST;
    const nightI = _smooth01(getNightIntensity());
    const goldT = getGoldenHourIntensity();

    let light = _lerp3(LIGHT_DAY, LIGHT_NIGHT, nightI);
    if (goldT > 0.01) light = _lerp3(light, LIGHT_GOLD, goldT * 0.85);

    // The biome colour carried by that light. At night the light dominates —
    // moonlight flattens local colour toward blue, which is exactly what it
    // does in reality.
    let tint = _lerp3(bm.tint, light, 0.55 + nightI * 0.30);
    let amt  = bm.amt + nightI * 0.10 + goldT * 0.12;
    let vib  = bm.vib + goldT * 0.10 - nightI * 0.04;
    let bloom = 0.30 + goldT * 0.25 + nightI * 0.10;
    let desat = 0;

    // Overcast light is flat and cool. Tinting alone barely reads as weather —
    // what actually sells "grey day" is losing colour, so rain drives a real
    // desaturation pass rather than just another wash.
    if (typeof weather !== 'undefined' && weather && weather.intensity > 0.05) {
      const w = Math.min(1, weather.intensity);
      tint = _lerp3(tint, [140, 160, 195], w * 0.65);
      vib -= w * 0.12;
      amt += w * 0.10;
      desat += w * 0.30;
      bloom *= 1 - w * 0.4;
    }

    // Underground there is no sky light left to carry the biome's colour, so
    // the grade turns cold and close. This is the single strongest cue that
    // you've left the surface behind — and it's free, because it's the same
    // pass that was already running.
    const depth01 = Math.max(0, Math.min(1, (player.y / TILE - 72) / 38));
    if (depth01 > 0) {
      tint = _lerp3(tint, CAVE_TINT, depth01 * 0.75);
      amt += depth01 * 0.12;
      vib -= depth01 * 0.06;
      desat += depth01 * 0.18; // rock underground reads muted, not colourful
      bloom += depth01 * 0.20; // torches matter more the darker it gets
    }

    return { tint, amt, vib: Math.max(0, vib), bloom: Math.max(0, bloom),
             desat: Math.max(0, Math.min(0.8, desat)) };
  }

  // Cheap bloom. There is no per-pixel work anywhere in here: the downscale
  // isolates nothing by itself, so brightness is separated by multiplying the
  // small buffer into itself twice (c⁴ — midtones collapse toward black while
  // near-white survives), and the blur is simply the smoothing filter doing its
  // job on the way back up.
  function drawBloom(strength) {
    const w = canvas.width, h = canvas.height;
    const mw = Math.max(64, Math.round(w / 3)), mh = Math.max(36, Math.round(h / 3));
    const bw = Math.max(32, Math.round(w / BLOOM_DIV)), bh = Math.max(18, Math.round(h / BLOOM_DIV));
    const ww = Math.max(12, Math.round(w / BLOOM_WIDE_DIV)), wh = Math.max(8, Math.round(h / BLOOM_WIDE_DIV));

    if (!bloomCv) {
      bloomCv = document.createElement('canvas');
      bloomCx = bloomCv.getContext('2d');
      bloomMid = document.createElement('canvas');
      bloomMidCx = bloomMid.getContext('2d');
      bloomWide = document.createElement('canvas');
      bloomWideCx = bloomWide.getContext('2d');
    }
    if (bloomMid.width !== mw || bloomMid.height !== mh) { bloomMid.width = mw; bloomMid.height = mh; }
    if (bloomCv.width !== bw || bloomCv.height !== bh) { bloomCv.width = bw; bloomCv.height = bh; }
    if (bloomWide.width !== ww || bloomWide.height !== wh) { bloomWide.width = ww; bloomWide.height = wh; }

    // Step 1 — take the frame down to a third, then isolate the bright parts
    // while there is still enough resolution for the threshold to be meaningful.
    // Multiplying the buffer into itself twice gives c⁴: midtones collapse
    // toward black, near-white survives. That's a luminance threshold without a
    // single per-pixel operation.
    bloomMidCx.globalCompositeOperation = 'source-over';
    bloomMidCx.globalAlpha = 1;
    bloomMidCx.clearRect(0, 0, mw, mh);
    bloomMidCx.drawImage(canvas, 0, 0, mw, mh);
    bloomMidCx.globalCompositeOperation = 'multiply';
    bloomMidCx.drawImage(bloomMid, 0, 0);
    bloomMidCx.drawImage(bloomMid, 0, 0);
    bloomMidCx.globalCompositeOperation = 'source-over';

    // Step 2 — a second downscale. Two successive box-filtered halvings
    // approximate a gaussian far better than one big jump, which is what turns
    // the result into a soft halo instead of a hard-edged smear.
    bloomCx.globalCompositeOperation = 'source-over';
    bloomCx.globalAlpha = 1;
    bloomCx.clearRect(0, 0, bw, bh);
    bloomCx.drawImage(bloomMid, 0, 0, bw, bh);

    // Step 3 — one more reduction, purely for the wide tail.
    bloomWideCx.globalCompositeOperation = 'source-over';
    bloomWideCx.globalAlpha = 1;
    bloomWideCx.clearRect(0, 0, ww, wh);
    bloomWideCx.drawImage(bloomCv, 0, 0, ww, wh);

    // Additive on the way back up; the upscale filter is the blur. Two levels
    // stacked: the tight one carries the bright core, the coarse one the faint
    // halo that keeps the falloff from ending in a visible edge.
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = Math.min(0.75, strength);
    ctx.drawImage(bloomCv, 0, 0, w, h);
    ctx.globalAlpha = Math.min(0.45, strength * 0.55);
    ctx.drawImage(bloomWide, 0, 0, w, h);
  }

  // Runs once per frame, over the finished world image.
  function grade() {
    const strength = ATMO_STRENGTH[atmosphere] || 0;
    if (strength <= 0) return;
    const m = currentMood();
    if (!m) return;

    const vib = m.vib * strength;
    const amt = m.amt * strength;
    // Bloom is the only genuinely costly pass, so it's also the first thing
    // given up: not at 'subtle', and never while the scaler has already had to
    // drop the buffer to keep up. The two halves share one budget.
    const bloom = (atmosphere === 'rich' && rung >= BLOOM_MIN_RUNG) ? m.bloom * strength : 0;

    const desat = (m.desat || 0) * strength;

    try {
      if (vib > 0.005) {
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = Math.min(0.60, vib);
        ctx.drawImage(canvas, 0, 0);
      }
      // Colour is pulled out BEFORE the ambient wash goes on, so what's left is
      // lit by the scene's light rather than by the block palette's own idea of
      // what colour it should be. This is what makes a downpour feel grey and a
      // deep cave feel like bare rock.
      if (desat > 0.005) {
        ctx.globalCompositeOperation = 'saturation';
        ctx.globalAlpha = Math.min(0.8, desat);
        ctx.fillStyle = '#808080'; // a zero-saturation source drains saturation
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
      if (amt > 0.005) {
        ctx.globalCompositeOperation = 'soft-light';
        ctx.globalAlpha = Math.min(0.85, amt * 2.2);
        ctx.fillStyle = 'rgb(' + (m.tint[0]|0) + ',' + (m.tint[1]|0) + ',' + (m.tint[2]|0) + ')';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
      if (bloom > 0.01) drawBloom(bloom);
    } finally {
      // Everything drawn after this point (vignettes, damage flashes, the HUD
      // chain) assumes a clean context. Leaving a blend mode set here would
      // corrupt all of it, so the reset is unconditional.
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
    }
  }

  function setAtmosphere(next) {
    if (ATMO_STRENGTH[next] === undefined) return;
    atmosphere = next;
    try { localStorage.setItem(LS_ATMO, next); } catch (e) {}
    refreshReadout();
  }

  function status() {
    return {
      mode: mode,
      label: MODES[mode].label,
      rung: rung,
      scale: scale,
      w: canvas.width,
      h: canvas.height,
      cols: COLS,
      rows: ROWS,
      fps: lastFps,
      native: scale >= 0.999,
      atmosphere: atmosphere,
      bloomActive: atmosphere === 'rich' && rung >= BLOOM_MIN_RUNG,
    };
  }

  // Live "what's active right now" caption in the settings panel — plain
  // language for players, not the raw buffer size or internal effect names.
  function refreshReadout() {
    const el = document.getElementById('vibrantvox-readout');
    if (!el) return;
    const pct = Math.round(scale * 100);
    const resText = scale >= 0.999 ? 'Full resolution' : pct + '% resolution';
    const lightText = atmosphere === 'off' ? '' :
      (atmosphere === 'rich' && rung >= BLOOM_MIN_RUNG) ? ' · Enhanced lighting' : ' · Basic lighting';
    el.textContent = resText + lightText;
  }

  function syncSelect() {
    const sel = document.getElementById('vibrantvox-mode');
    if (sel) sel.value = mode;
    const atmo = document.getElementById('vibrantvox-atmosphere');
    if (atmo) atmo.value = atmosphere;
    refreshReadout();
  }

  return { apply, frame, grade, setAtmosphere, status, syncSelect, refreshReadout,
           get mode() { return mode; }, get atmosphere() { return atmosphere; } };
})();
window.VibrantVox = VibrantVox;

// Kept as a named function because several listeners below (and the historic
// mobile/orientation paths) already reference it; it is now just VibrantVox's
// resize entry point.
function fitMobileCanvas() { VibrantVox.apply(); }
fitMobileCanvas();
// Layout (info-bar wrapping, fonts, etc.) isn't always settled yet on the
// first synchronous pass, so re-check shortly after once the page has
// actually finished laying out.
requestAnimationFrame(() => requestAnimationFrame(fitMobileCanvas));
window.addEventListener('load', fitMobileCanvas);
window.addEventListener('resize', fitMobileCanvas);
window.addEventListener('orientationchange', () => setTimeout(fitMobileCanvas, 60));
document.addEventListener('fullscreenchange', () => setTimeout(fitMobileCanvas, 60));
document.addEventListener('webkitfullscreenchange', () => setTimeout(fitMobileCanvas, 60));
if (window.visualViewport) window.visualViewport.addEventListener('resize', fitMobileCanvas);

let activeDynamites = [];

let audioCtx;
let masterGain; // all SFX/music route through this so the volume slider affects everything at once
function getMasterVolume() {
  try {
    const v = parseFloat(localStorage.getItem('voxeria_master_volume'));
    return isNaN(v) ? 1 : Math.min(1, Math.max(0, v));
  } catch (e) { return 1; }
}
function setMasterVolume(v) {
  v = Math.min(1, Math.max(0, v));
  try { localStorage.setItem('voxeria_master_volume', String(v)); } catch (e) {}
  if (masterGain) masterGain.gain.value = v;
}

// ── Background Music Player ──────────────────────────────────────────────────
const MUSIC_B64 = "";
// The soundtrack. The first track is embedded as base64 above and is therefore
// ALWAYS available — no file, no network, no server needed. The other two are
// ordinary files under Music/ and are fetched on demand: at ~9 MB together,
// base64-ing them into this file would have added ~12 MB of source that every
// player downloads before the game can even start parsing.
//
// A file that cannot be fetched or decoded (missing from the build, opened via
// file://, half-downloaded) is marked broken and silently dropped from the
// rotation — the embedded track keeps the music going on its own.
const MUSIC_TRACKS = [
  { title: 'Feltklavier Wolke', b64: MUSIC_B64 },
  { title: 'Glasnebel Herz',    url: 'Music/Glasnebel Herz.mp3' },
  { title: 'Silberne Tasten',   url: 'Music/Silberne Tasten.mp3' }
];

const _musicBuffers = MUSIC_TRACKS.map(() => null);
const _musicBroken  = MUSIC_TRACKS.map(() => false);
const _musicLoading = MUSIC_TRACKS.map(() => false);
const _musicWaiters = MUSIC_TRACKS.map(() => []);   // callbacks parked on an in-flight load

let _musicQueue = [];        // shuffled indices, consumed one track at a time
let _musicNowPlaying = -1;

let bgMusicSource = null;
let bgMusicGain = null;
let bgMusicScheduled = false;
// The main menu is a full-screen opaque overlay: while it is up the player is
// not in a world yet, so nothing may play behind it. Tracks are still LOADED
// during that time (so one is ready the instant a world opens) — only STARTING
// playback waits for the menu to close. See startBgMusic/stopBgMusic.
let bgMusicWanted = false;

function vxMenuIsOpen() {
  const m = document.getElementById('vx-menu');
  return !!m && m.classList.contains('show');
}
window.vxMenuIsOpen = vxMenuIsOpen;

// Fetch + decode one track. Every caller goes through here, so a track is
// downloaded and decoded at most once per session even if two things ask for
// it while it is still in flight — the second one parks in _musicWaiters
// instead of starting a second fetch. cb(buffer) or cb(null) when unplayable.
function loadMusicTrack(i, cb) {
  if (!audioCtx || _musicBroken[i]) { if (cb) cb(null); return; }
  if (_musicBuffers[i]) { if (cb) cb(_musicBuffers[i]); return; }
  if (cb) _musicWaiters[i].push(cb);
  if (_musicLoading[i]) return;
  _musicLoading[i] = true;

  const track = MUSIC_TRACKS[i];
  const done = function (buf) {
    _musicLoading[i] = false;
    _musicBuffers[i] = buf;
    if (!buf) _musicBroken[i] = true;
    for (const w of _musicWaiters[i].splice(0)) w(buf);
  };
  const decode = function (arrayBuffer) {
    audioCtx.decodeAudioData(arrayBuffer, done, function (e) {
      console.warn('Music decode failed: ' + track.title, e);
      done(null);
    });
  };

  if (track.b64) {
    const binary = atob(track.b64);
    const bytes = new Uint8Array(binary.length);
    for (let k = 0; k < binary.length; k++) bytes[k] = binary.charCodeAt(k);
    decode(bytes.buffer);
  } else {
    // encodeURI, because the file names contain spaces.
    fetch(encodeURI(track.url))
      .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.arrayBuffer(); })
      .then(decode)
      .catch(e => { console.warn('Music file unavailable: ' + track.url, e); done(null); });
  }
}

// Shuffled rotation rather than a fixed order, so a session doesn't always
// open with the same piece. `avoid` is the track that just played: it may not
// land first in the fresh queue, otherwise the wrap-around point would be the
// one place the same piece could play twice in a row.
function _refillMusicQueue(avoid) {
  const pool = [];
  for (let i = 0; i < MUSIC_TRACKS.length; i++) if (!_musicBroken[i]) pool.push(i);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = pool[i]; pool[i] = pool[j]; pool[j] = t;
  }
  if (pool.length > 1 && pool[0] === avoid) pool.push(pool.shift());
  _musicQueue = pool;
}

// Every restart bumps this; a stale source's onended — or a track whose load
// finishes after we moved on — checks it before doing anything, so a late
// async event from something we already replaced can never resurrect itself or
// double-schedule a restart timer. Simpler and more robust than comparing node
// identity.
let bgMusicGen = 0;

function _stopBgMusicSource() {
  if (!bgMusicSource) return;
  bgMusicSource.onended = null; // we're stopping it on purpose; don't run its "track ended naturally" logic
  try { bgMusicSource.stop(); } catch(e) {}
  bgMusicSource = null;
  if (bgMusicGain) { try { bgMusicGain.disconnect(); } catch(e) {} bgMusicGain = null; }
}

// Starts the next track in the rotation. Kept under its old name because the
// seed/mod paths further down call it.
function scheduleBgMusic(delaySeconds) {
  if (!audioCtx) return;
  if (vxMenuIsOpen()) return; // never audible behind the main menu
  bgMusicScheduled = true;
  const myGen = ++bgMusicGen;
  _stopBgMusicSource();
  _playNextTrack(delaySeconds, myGen, 0);
}

// `attempt` bounds the walk down the queue when tracks turn out to be
// unplayable, so a build with both files missing tries each one once and
// settles on the embedded track instead of spinning.
function _playNextTrack(delaySeconds, myGen, attempt) {
  if (!_musicQueue.length) _refillMusicQueue(_musicNowPlaying);
  const idx = _musicQueue.length ? _musicQueue.shift() : -1;
  if (idx < 0) { bgMusicScheduled = false; return; } // nothing playable at all

  loadMusicTrack(idx, function (buf) {
    // Loading a file takes long enough that the player can be back in the menu
    // (or in another world) by the time it lands.
    if (myGen !== bgMusicGen || !bgMusicWanted || vxMenuIsOpen()) { return; }
    if (!buf) {
      if (attempt + 1 >= MUSIC_TRACKS.length) { bgMusicScheduled = false; return; }
      _playNextTrack(delaySeconds, myGen, attempt + 1);
      return;
    }
    _startMusicTrack(idx, buf, delaySeconds, myGen);
  });
}

function _startMusicTrack(idx, buf, delaySeconds, myGen) {
  _musicNowPlaying = idx;
  window._vxNowPlaying = MUSIC_TRACKS[idx].title; // visible in the console

  bgMusicGain = audioCtx.createGain();
  bgMusicGain.gain.value = 0.5;
  bgMusicGain.connect(masterGain);

  bgMusicSource = audioCtx.createBufferSource();
  bgMusicSource.buffer = buf;
  bgMusicSource.connect(bgMusicGain);
  bgMusicSource.start(audioCtx.currentTime + delaySeconds);
  bgMusicSource.onended = function() {
    if (myGen !== bgMusicGen) return; // a newer restart already took over
    bgMusicSource = null;
    bgMusicScheduled = false;
    // Pull the upcoming track in during the quiet gap, so a 5 MB file isn't
    // downloaded at the moment it is supposed to start playing.
    if (!_musicQueue.length) _refillMusicQueue(idx);
    if (_musicQueue.length) loadMusicTrack(_musicQueue[0], null);
    setTimeout(function() {
      if (myGen === bgMusicGen && bgMusicWanted && audioCtx) scheduleBgMusic(0);
    }, 5 * 60 * 1000);
  };
}

// Preload only — playback is startBgMusic's job. The embedded track costs
// nothing to have ready, and the head of the queue is fetched while the player
// is still reading the menu rather than after they press Play.
function loadBgMusic() {
  if (!audioCtx) return;
  loadMusicTrack(0, null);
  if (!_musicQueue.length) _refillMusicQueue(-1);
  if (_musicQueue.length) loadMusicTrack(_musicQueue[0], null);
}

// The two calls the rest of the game uses to say "the player is in a world" /
// "the player is not". Everything else about the music is internal.
function startBgMusic() {
  bgMusicWanted = true;
  if (!audioCtx || vxMenuIsOpen()) return; // initAudio()/hide() come back for it
  if (bgMusicSource || bgMusicScheduled) return; // already playing, or a load is on its way
  scheduleBgMusic(0);
}

function stopBgMusic() {
  bgMusicWanted = false;
  bgMusicGen++;        // invalidate any pending 5-minute restart timer and any in-flight load
  _stopBgMusicSource();
  bgMusicScheduled = false;
}

window.vxStartBgMusic = startBgMusic;
window.vxStopBgMusic = stopBgMusic;

function restartBgMusicFromSeed() {
  if (!audioCtx) return;
  stopBgMusic();
  if (vxMenuIsOpen()) return; // a seed change made from the menu stays silent
  startBgMusic();
}
// ─────────────────────────────────────────────────────────────────────────────


function initAudio() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  window._vAudio = audioCtx;
  if (!masterGain) {
    masterGain = audioCtx.createGain();
    masterGain.gain.value = getMasterVolume();
    masterGain.connect(audioCtx.destination);
  }
  // Always re-sync to the current (effective) mute state here, since this can run
  // AFTER the SDK settings listener already set the mute flags — a freshly
  // created AudioContext otherwise starts audible regardless of that.
  if (typeof _effectiveMuted === 'function' && _effectiveMuted()) {
    try { audioCtx.suspend().catch(e => console.error("initAudio suspend error:", e)); } catch (e) { console.error("initAudio suspend error:", e); }
  } else if (audioCtx.state === 'suspended') {
    try { audioCtx.resume().catch(e => console.error("initAudio resume error:", e)); } catch (e) { console.error("initAudio resume error:", e); }
  }
  // Decode either way — but the first gesture that gets us here is usually a
  // click in the main menu, and the menu must stay silent.
  loadBgMusic();
  loadUiClickSound();
  loadUiHoverSound();
  loadUiTypeSound();
  loadGrassDestroySound();
  loadGrassPlaceSound();
  loadModNodeTouchSound();
  loadModNodePullSound();
  loadModNodePlopSound();
  loadBlockSamples();
  if (!vxMenuIsOpen()) startBgMusic();
}

// ── UI Click Sound ──────────────────────────────────────────────────────────
// A real recorded sample rather than a synthesized tone, used for every
// button/[onclick]/.slot press across the whole game (see FX_BUTTON_SELECTOR
// below). Embedded as base64 for the same reason as the first music track
// (see MUSIC_B64 above): this plays on the very first click in the main menu,
// before any asset folder has had a chance to load, so it cannot depend on a
// separate file fetch. At ~230 KB of base64 for a ~1s clip, the cost is
// negligible next to the file this already lives in.
const UI_CLICK_B64 = "";
let _uiClickBuffer = null;
let _uiClickBroken = false;
// Decoded once per session, lazily, the first time it's actually needed
// (initAudio only runs after a real user gesture) — decodeAudioData on a
// quarter-megabyte string is cheap, but there's no reason to pay it before
// audio is even unlocked.
function loadUiClickSound() {
  if (!audioCtx || _uiClickBuffer || _uiClickBroken) return;
  const binary = atob(UI_CLICK_B64);
  const bytes = new Uint8Array(binary.length);
  for (let k = 0; k < binary.length; k++) bytes[k] = binary.charCodeAt(k);
  audioCtx.decodeAudioData(bytes.buffer, buf => { _uiClickBuffer = buf; }, e => {
    console.warn('UI click sound decode failed, falling back to the synthesized tone', e);
    _uiClickBroken = true;
  });
}

