// Small pitch wobble so mining/placing a run of grass blocks doesn't play
// the exact same sample back to back to back.
function _grassPlaybackRate() { return 0.96 + Math.random() * 0.08; }

// Dynamic start/stop rather than "always play the whole file to the end":
// both recordings run several seconds long, but the game action they're
// for is usually much shorter -- a single click breaks grass instantly, and
// even the full desktop hold-to-mine charge for grass is capped at 1s (see
// HOLD_MS_PER_HARDNESS). Playing the sample out to its natural end left it
// still ringing seconds after the block was already gone. Each pair below
// tracks one in-flight source and is idempotent to start -- calling the
// starter again while one is already playing does nothing -- so the 280ms
// mining-hit pulse in updateMiningHold can call it on every pulse without
// ever layering duplicate copies of the same sample.
let _grassDestroySource = null, _grassDestroyGain = null;
function _startGrassDestroy() {
  if (_grassDestroySource || !_grassDestroyBuffer || !audioCtx) return;
  const t = audioCtx.currentTime;
  const gain = audioCtx.createGain();
  gain.connect(masterGain);
  const src = audioCtx.createBufferSource();
  src.buffer = _grassDestroyBuffer;
  src.playbackRate.value = _grassPlaybackRate();
  src.connect(gain);
  gain.gain.setValueAtTime(0.55, t);
  src.start(t);
  src.onended = () => { if (_grassDestroySource === src) { _grassDestroySource = null; _grassDestroyGain = null; } };
  _grassDestroySource = src; _grassDestroyGain = gain;
}
// tailSec: how much longer to let it ring past this moment before cutting
// it -- a hard cut exactly on the triggering frame reads as clipped. 0 (or
// omitted) stops it essentially immediately, for when mining was abandoned
// outright rather than completed.
function _stopGrassDestroy(tailSec) {
  if (!_grassDestroySource || !audioCtx) return;
  const t = audioCtx.currentTime;
  const src = _grassDestroySource, gain = _grassDestroyGain;
  const stopAt = t + (tailSec || 0);
  const fadeStart = Math.max(t, stopAt - 0.05);
  try {
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(gain.gain.value, fadeStart);
    gain.gain.linearRampToValueAtTime(0, stopAt);
    src.stop(stopAt + 0.01);
  } catch (e) {}
  _grassDestroySource = null; _grassDestroyGain = null;
}

let _grassPlaceSource = null, _grassPlaceGain = null;
function _startGrassPlace() {
  if (_grassPlaceSource || !_grassPlaceBuffer || !audioCtx) return;
  const t = audioCtx.currentTime;
  const gain = audioCtx.createGain();
  gain.connect(masterGain);
  const src = audioCtx.createBufferSource();
  src.buffer = _grassPlaceBuffer;
  src.playbackRate.value = _grassPlaybackRate();
  src.connect(gain);
  gain.gain.setValueAtTime(0.55, t);
  src.start(t);
  src.onended = () => { if (_grassPlaceSource === src) { _grassPlaceSource = null; _grassPlaceGain = null; } };
  _grassPlaceSource = src; _grassPlaceGain = gain;
}
function _stopGrassPlace(tailSec) {
  if (!_grassPlaceSource || !audioCtx) return;
  const t = audioCtx.currentTime;
  const src = _grassPlaceSource, gain = _grassPlaceGain;
  const stopAt = t + (tailSec || 0);
  const fadeStart = Math.max(t, stopAt - 0.05);
  try {
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(gain.gain.value, fadeStart);
    gain.gain.linearRampToValueAtTime(0, stopAt);
    src.stop(stopAt + 0.01);
  } catch (e) {}
  _grassPlaceSource = null; _grassPlaceGain = null;
}

function playSound(type) {
  if (!audioCtx) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.connect(gain); gain.connect(masterGain);

  if (type === 'jump') {
    osc.type = 'sine';
    osc.frequency.setValueAtTime(300, t); osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);
    gain.gain.setValueAtTime(0.2, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 0.15);
    osc.start(t); osc.stop(t + 0.15);
  } else if (type === 'place') {
    osc.type = 'sine';
    osc.frequency.setValueAtTime(400, t); osc.frequency.exponentialRampToValueAtTime(200, t + 0.1);
    gain.gain.setValueAtTime(0.3, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 0.1);
    osc.start(t); osc.stop(t + 0.1);
  } else if (type === 'buy') {
    osc.type = 'sine';
    osc.frequency.setValueAtTime(1000, t); osc.frequency.setValueAtTime(1500, t + 0.1);
    gain.gain.setValueAtTime(0.2, t); gain.gain.linearRampToValueAtTime(0, t + 0.3);
    osc.start(t); osc.stop(t + 0.3);
  } else if (type === 'portal') {
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(200, t); osc.frequency.exponentialRampToValueAtTime(800, t + 1.5);
    gain.gain.setValueAtTime(0.4, t); gain.gain.linearRampToValueAtTime(0, t + 1.5);
    osc.start(t); osc.stop(t + 1.5);
  } else if (type === 'hurt') {
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(200, t); osc.frequency.exponentialRampToValueAtTime(80, t + 0.2);
    gain.gain.setValueAtTime(0.35, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 0.2);
    osc.start(t); osc.stop(t + 0.2);
  } else if (type === 'bite') {
    osc.type = 'square';
    osc.frequency.setValueAtTime(800, t); osc.frequency.exponentialRampToValueAtTime(200, t + 0.12);
    gain.gain.setValueAtTime(0.25, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 0.12);
    osc.start(t); osc.stop(t + 0.12);
  } else if (type === 'thunder') {
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(60, t); osc.frequency.exponentialRampToValueAtTime(20, t + 1.2);
    gain.gain.setValueAtTime(0.5, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 1.2);
    osc.start(t); osc.stop(t + 1.2);
  } else if (type === 'explode') {
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, t); osc.frequency.exponentialRampToValueAtTime(30, t + 0.6);
    gain.gain.setValueAtTime(0.6, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.8);
    osc.start(t); osc.stop(t + 0.8);
    // Second oscillator for rumble
    const osc2 = audioCtx.createOscillator();
    const gain2 = audioCtx.createGain();
    osc2.connect(gain2); gain2.connect(masterGain);
    osc2.type = 'square';
    osc2.frequency.setValueAtTime(80, t); osc2.frequency.exponentialRampToValueAtTime(20, t + 0.5);
    gain2.gain.setValueAtTime(0.3, t); gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
    osc2.start(t); osc2.stop(t + 0.6);
  } else if (type === 'alarm') {
    // Two-tone siren announcing an incoming world event
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(440, t); osc.frequency.linearRampToValueAtTime(660, t + 0.22);
    osc.frequency.setValueAtTime(440, t + 0.44); osc.frequency.linearRampToValueAtTime(660, t + 0.66);
    gain.gain.setValueAtTime(0.22, t); gain.gain.setValueAtTime(0.22, t + 0.8); gain.gain.linearRampToValueAtTime(0, t + 1.0);
    osc.start(t); osc.stop(t + 1.0);
  } else if (type === 'meteor') {
    // Short whoosh-boom for meteor impacts — softer than 'explode' since
    // several can land per second during a shower
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(220, t); osc.frequency.exponentialRampToValueAtTime(40, t + 0.35);
    gain.gain.setValueAtTime(0.28, t); gain.gain.exponentialRampToValueAtTime(0.01, t + 0.4);
    osc.start(t); osc.stop(t + 0.4);
  } else if (type === 'reward') {
    osc.type = 'triangle';
    [523.25, 659.25, 783.99, 1046.5].forEach((freq, i) => {
      osc.frequency.setValueAtTime(freq, t + i * 0.09);
    });
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.3, t + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    osc.start(t); osc.stop(t + 0.45);
  } else if (type === 'click') {
    // The recorded sample (see UI_CLICK_B64) plays when it's ready; the
    // synthesized sweep below is only the fallback for the handful of clicks
    // that can land before decodeAudioData finishes, or if it ever fails.
    // Both branches route through `gain`/masterGain, so this stays subject to
    // the same volume and mute handling as every other sound in the game.
    if (_uiClickBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _uiClickBuffer;
      src.connect(gain);
      gain.gain.setValueAtTime(0.5, t);
      src.start(t);
      return;
    }
    osc.type = 'sine';
    osc.frequency.setValueAtTime(700, t); osc.frequency.exponentialRampToValueAtTime(1100, t + 0.07);
    gain.gain.setValueAtTime(0.18, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.09);
    osc.start(t); osc.stop(t + 0.09);
  } else if (type === 'hover') {
    // Same real-sample-with-synthesized-fallback structure as 'click' just
    // above (see HOVER_CLICK_B64). Quieter than click (0.22 vs click's 0.5):
    // this fires on every mouse pass over a button, not just a deliberate
    // press, and would get fatiguing fast at click volume.
    if (_uiHoverBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _uiHoverBuffer;
      src.connect(gain);
      gain.gain.setValueAtTime(0.22, t);
      src.start(t);
      return;
    }
    osc.type = 'sine';
    osc.frequency.setValueAtTime(500, t); osc.frequency.exponentialRampToValueAtTime(650, t + 0.05);
    gain.gain.setValueAtTime(0.08, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    osc.start(t); osc.stop(t + 0.06);
  } else if (type === 'type') {
    // Same real-sample-with-synthesized-fallback structure as click/hover
    // (see TYPE_CLICK_B64). One of these plays per keystroke while typing
    // into any real text field (see the delegated 'input' listener near
    // FX_BUTTON_SELECTOR below), so it's pitched a hair differently each
    // time -- a mechanical-keyboard sample repeated at the exact same pitch
    // dozens of times a second while someone types a mod name reads as a
    // loop, not a keyboard.
    if (_uiTypeBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _uiTypeBuffer;
      src.playbackRate.value = 0.94 + Math.random() * 0.12;
      src.connect(gain);
      gain.gain.setValueAtTime(0.3, t);
      src.start(t);
      return;
    }
    osc.type = 'square';
    osc.frequency.setValueAtTime(900 + Math.random() * 200, t);
    gain.gain.setValueAtTime(0.06, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
    osc.start(t); osc.stop(t + 0.03);
  } else if (type === 'denied') {
    osc.type = 'square';
    osc.frequency.setValueAtTime(160, t); osc.frequency.exponentialRampToValueAtTime(100, t + 0.12);
    gain.gain.setValueAtTime(0.12, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    osc.start(t); osc.stop(t + 0.12);
  } else if (type === 'hiss') {
    // Steam sizzle — filtered white-noise burst for lava meeting water.
    const dur = 0.4;
    const buffer = audioCtx.createBuffer(1, Math.floor(audioCtx.sampleRate * dur), audioCtx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
    const noise = audioCtx.createBufferSource(); noise.buffer = buffer;
    const lp = audioCtx.createBiquadFilter(); lp.type = 'bandpass'; lp.frequency.value = 3600; lp.Q.value = 0.7;
    const ng = audioCtx.createGain(); ng.gain.setValueAtTime(0.16, t); ng.gain.exponentialRampToValueAtTime(0.001, t + dur);
    noise.connect(lp); lp.connect(ng); ng.connect(masterGain);
    noise.start(t); noise.stop(t + dur);
  } else if (type === 'modNodeTouch') {
    // Releasing a dragged node in the Mod Editor. Same recorded-sample-with-
    // synthesized-fallback shape as 'click'/'hover'/'type' above.
    if (_modNodeTouchBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _modNodeTouchBuffer;
      src.connect(gain);
      gain.gain.setValueAtTime(0.4, t);
      src.start(t);
      return;
    }
    osc.type = 'sine';
    osc.frequency.setValueAtTime(500, t); osc.frequency.exponentialRampToValueAtTime(350, t + 0.08);
    gain.gain.setValueAtTime(0.18, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    osc.start(t); osc.stop(t + 0.08);
  } else if (type === 'modNodePull') {
    // Starting to drag a wire off a node's output port. Fired once per pull
    // (at pointerdown on the port), not per pointermove frame; see the
    // ng-port pointerdown handler in voxeria-modding.js.
    if (_modNodePullBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _modNodePullBuffer;
      src.connect(gain);
      gain.gain.setValueAtTime(0.35, t);
      src.start(t);
      return;
    }
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(300, t); osc.frequency.exponentialRampToValueAtTime(500, t + 0.1);
    gain.gain.setValueAtTime(0.15, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    osc.start(t); osc.stop(t + 0.1);
  } else if (type === 'modNodePlop') {
    // A wire snaps onto a valid target node. See ngConnect() in
    // voxeria-modding.js, the one place a connection is actually made.
    if (_modNodePlopBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = _modNodePlopBuffer;
      src.connect(gain);
      gain.gain.setValueAtTime(0.45, t);
      src.start(t);
      return;
    }
    osc.type = 'sine';
    osc.frequency.setValueAtTime(600, t); osc.frequency.exponentialRampToValueAtTime(900, t + 0.06);
    gain.gain.setValueAtTime(0.25, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.09);
    osc.start(t); osc.stop(t + 0.09);
  }
}

// playBlockSound() lives further down, right after BLOCKS/blockColors/blockNames
// are defined — the per-block sound table is keyed by BLOCKS.* and needs those
// to exist first. See the BLOCK MINING SOUNDS section.

// A plain three-way {once:true} triple here is a footgun: each listener is
// "once" independently, so if the player's first gesture is e.g. a keydown,
// the click/touchstart listeners stay armed and initAudio() fires AGAIN on
// the next click (their first mining click) or tap. initAudio()/loadBgMusic()
// are idempotent so this couldn't double the music, but it's needless replay
// of the mute-resync logic — one shared flag removes all three cleanly.
(function () {
  let unlocked = false;
  function unlockAudio() {
    if (unlocked) return;
    unlocked = true;
    window.removeEventListener('click', unlockAudio);
    window.removeEventListener('keydown', unlockAudio);
    window.removeEventListener('touchstart', unlockAudio);
    initAudio();
  }
  window.addEventListener('click', unlockAudio);
  window.addEventListener('keydown', unlockAudio);
  window.addEventListener('touchstart', unlockAudio);
})();

// =========================================================
// BUTTON JUICE — instant, satisfying feedback on every UI button click
// =========================================================
const FX_BUTTON_SELECTOR = 'button, [onclick], .slot';
const FX_SPARK_COLORS = ['#ffe066', '#4facfe', '#ff6b6b', '#a8ff78', '#c084fc'];

function fxRestartClass(el, cls, duration) {
  el.classList.remove(cls);
  void el.offsetWidth; // force reflow so the animation restarts on rapid clicks
  el.classList.add(cls);
  clearTimeout(el._fxTimeout);
  el._fxTimeout = setTimeout(() => el.classList.remove(cls), duration);
}

function fxSpawnRipple(cx, cy, size) {
  const ripple = document.createElement('span');
  ripple.className = 'fx-ripple';
  ripple.style.left = (cx - size / 2) + 'px';
  ripple.style.top = (cy - size / 2) + 'px';
  ripple.style.width = ripple.style.height = size + 'px';
  document.body.appendChild(ripple);
  setTimeout(() => ripple.remove(), 520);
}

function fxSpawnSparks(cx, cy) {
  for (let i = 0; i < 6; i++) {
    const spark = document.createElement('span');
    const angle = (Math.PI * 2 * i / 6) + (Math.random() * 0.5 - 0.25);
    const dist = 20 + Math.random() * 14;
    spark.className = 'fx-spark';
    spark.style.left = cx + 'px';
    spark.style.top = cy + 'px';
    spark.style.color = FX_SPARK_COLORS[i % FX_SPARK_COLORS.length];
    spark.style.background = FX_SPARK_COLORS[i % FX_SPARK_COLORS.length];
    document.body.appendChild(spark);
    requestAnimationFrame(() => {
      spark.style.transform = `translate(${Math.cos(angle) * dist}px, ${Math.sin(angle) * dist}px) scale(0)`;
      spark.style.opacity = '0';
    });
    setTimeout(() => spark.remove(), 440);
  }
}

document.addEventListener('click', function (e) {
  const target = e.target.closest(FX_BUTTON_SELECTOR);
  if (!target) return;
  const rect = target.getBoundingClientRect();
  const cx = (e.clientX || (rect.left + rect.width / 2));
  const cy = (e.clientY || (rect.top + rect.height / 2));

  if (target.classList.contains('disabled')) {
    fxRestartClass(target, 'fx-deny', 320);
    playSound('denied');
    return;
  }

  fxRestartClass(target, 'fx-pop', 280);
  fxSpawnRipple(cx, cy, Math.max(rect.width, rect.height) * 1.3);
  fxSpawnSparks(cx, cy);
  playSound('click');
}, true);

// mouseover (not mouseenter) because delegation needs a bubbling event; the
// e.relatedTarget check below is what turns repeated mouseover firing as the
// cursor moves between a button's own children back into a single "entered
// from outside" trigger, the same job mouseenter does natively per-element.
document.addEventListener('mouseover', function (e) {
  const target = e.target.closest(FX_BUTTON_SELECTOR);
  if (!target) return;
  if (e.relatedTarget && target.contains(e.relatedTarget)) return;
  if (target.classList.contains('disabled')) return;
  playSound('hover');
}, true);

// 'input', not 'keydown': fires only when a field's value actually changed
// (typed, pasted, deleted, autofilled), not on every Tab/arrow/modifier
// press that passes through a field without writing anything into it.
// Checked via the .type IDL property, not an [type="..."] attribute
// selector: plenty of fields here (world name, seed, ...) never write a
// literal type="text" attribute since it's the HTML default, and the
// browser still normalizes .type to "text" for them -- an attribute
// selector would silently miss every one of those.
const FX_TYPE_KINDS = new Set(['text', 'password', 'number', 'search']);
document.addEventListener('input', function (e) {
  const el = e.target;
  const isTypable = el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && FX_TYPE_KINDS.has(el.type));
  if (!isTypable) return;
  playSound('type');
}, true);

