// =========================================================
// BLOCK MINING SOUNDS — layered WebAudio synthesis, one voice per material
// =========================================================
// Every hit calls playBlockSound(blockType). Instead of 5 generic buckets,
// each block gets its own BLOCK_SOUND entry: a family (the synthesis
// "engine" — stone knock, crystal chime, wood thunk, ...) plus a base
// frequency that gives it a distinct pitch within that family, so related
// materials (all the crystal ores, say) sound like siblings but stay
// tellable apart. A small random per-hit pitch wobble keeps repeated
// mining from sounding robotic.

function _sndTone(type, f0, f1, dur, vol, t) {
  const osc = audioCtx.createOscillator();
  const g = audioCtx.createGain();
  osc.connect(g); g.connect(masterGain);
  osc.type = type;
  osc.frequency.setValueAtTime(f0, t);
  if (f1 !== f0) osc.frequency.exponentialRampToValueAtTime(Math.max(f1, 1), t + dur);
  g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  osc.start(t); osc.stop(t + dur);
}

function _sndNoiseBurst(dur, vol, filterType, filterFreq, Q, t) {
  const n = Math.max(1, Math.floor(audioCtx.sampleRate * dur));
  const buffer = audioCtx.createBuffer(1, n, audioCtx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < n; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = audioCtx.createBufferSource(); src.buffer = buffer;
  const f = audioCtx.createBiquadFilter(); f.type = filterType; f.frequency.value = filterFreq; f.Q.value = Q;
  const g = audioCtx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  src.connect(f); f.connect(g); g.connect(masterGain);
  src.start(t); src.stop(t + dur);
}

function _sndClick(vol, t, dur) {
  _sndNoiseBurst(dur || 0.008, vol, 'highpass', 4000, 0.7, t);
}

const _BLOCK_SOUND_FX = {
  stone(f, t, d) {
    _sndTone('square', f * d, f * 0.17 * d, 0.1, 0.16, t);
    _sndClick(0.05, t);
  },
  denseStone(f, t, d) {
    _sndTone('square', f * d, f * 0.15 * d, 0.16, 0.22, t);
    _sndTone('sine', f * 0.5 * d, f * 0.1 * d, 0.2, 0.12, t);
    _sndClick(0.08, t, 0.012);
  },
  ore(f, t, d) {
    _sndTone('square', 300 * d, 50 * d, 0.1, 0.14, t);
    _sndTone('triangle', f * d, f * 0.6 * d, 0.08, 0.1, t);
    _sndClick(0.05, t);
  },
  shinyOre(f, t, d) {
    _sndTone('square', 300 * d, 60 * d, 0.09, 0.12, t);
    _sndTone('triangle', f * d, f * 1.4 * d, 0.18, 0.14, t);
    _sndTone('sine', f * 2 * d, f * 1.6 * d, 0.12, 0.06, t);
    _sndClick(0.06, t);
  },
  metalBrick(f, t, d) {
    _sndTone('triangle', f * d, f * 1.3 * d, 0.22, 0.16, t);
    _sndTone('sine', f * 2.01 * d, f * 1.7 * d, 0.16, 0.08, t);
    _sndTone('sine', f * 3 * d, f * 2.4 * d, 0.1, 0.04, t);
    _sndClick(0.07, t);
  },
  crystal(f, t, d, opts) {
    _sndTone('sine', f * 0.5 * d, f * 0.35 * d, 0.06, 0.08, t);
    _sndTone('triangle', f * d, f * 1.15 * d, 0.22, 0.13, t);
    _sndTone('sine', f * 1.5 * d, f * 1.4 * d, 0.18, 0.07, t);
    if (opts && opts.shimmer) _sndTone('triangle', f * 1.9 * d, f * 2.2 * d, 0.14, 0.05, t + 0.02);
    if (opts && opts.sizzle) _sndNoiseBurst(0.15, 0.05, 'highpass', 4000, 0.8, t);
    if (opts && opts.watery) _sndNoiseBurst(0.12, 0.04, 'bandpass', 2200, 1.2, t);
    _sndClick(0.04, t);
  },
  wood(f, t, d) {
    _sndTone('sawtooth', f * d, f * 0.33 * d, 0.1, 0.2, t);
    _sndClick(0.04, t);
  },
  shell(f, t, d) {
    _sndTone('sawtooth', f * d, f * 1.6 * d, 0.06, 0.15, t);
    _sndClick(0.07, t, 0.01);
  },
  glass(f, t, d) {
    _sndTone('triangle', f * 0.6 * d, f * d, 0.05, 0.2, t);
    _sndTone('sine', f * 1.6 * d, f * 2 * d, 0.09, 0.08, t + 0.01);
    _sndClick(0.03, t);
  },
  voidGlass(f, t, d) {
    _sndTone('triangle', f * 0.5 * d, f * 0.85 * d, 0.06, 0.16, t);
    _sndTone('sine', f * 2 * d, f * 0.9 * d, 0.35, 0.05, t);
    _sndClick(0.03, t);
  },
  dirtEarth(f, t, d, opts) {
    _sndTone('sine', f * d, f * 0.6 * d, 0.08, 0.14, t);
    _sndNoiseBurst(0.09, 0.07, 'bandpass', 1200, 0.9, t);
    if (opts && opts.shimmer) _sndTone('triangle', f * 4 * d, f * 3 * d, 0.15, 0.03, t + 0.03);
  },
  sand(f, t, d) {
    _sndNoiseBurst(0.14, 0.1, 'bandpass', 3200, 1.4, t);
    _sndTone('sine', 140 * d, 90 * d, 0.06, 0.06, t);
  },
  snow(f, t, d) {
    _sndNoiseBurst(0.12, 0.09, 'lowpass', 900, 0.6, t);
  },
  plant(f, t, d) {
    _sndTone('sine', f * d, f * 0.9 * d, 0.08, 0.12, t);
    _sndNoiseBurst(0.06, 0.04, 'highpass', 3500, 0.8, t);
  },
  coral(f, t, d) {
    _sndNoiseBurst(0.05, 0.12, 'highpass', 3000, 1.6, t);
    _sndTone('triangle', 900 * d, 500 * d, 0.05, 0.08, t);
  },
  kelp(f, t, d) {
    _sndNoiseBurst(0.16, 0.08, 'lowpass', 600, 0.7, t);
    _sndTone('sine', 180 * d, 90 * d, 0.14, 0.07, t);
  },
  heatRock(f, t, d) {
    _sndTone('square', f * d, f * 0.17 * d, 0.1, 0.15, t);
    _sndNoiseBurst(0.18, 0.03, 'bandpass', 3800, 0.7, t + 0.03);
    _sndClick(0.05, t);
  },
  chest(f, t, d) {
    _sndTone('sawtooth', 200 * d, 120 * d, 0.12, 0.16, t);
    [1, 1.3, 1.7].forEach((m, i) => _sndTone('triangle', 900 * m * d, 900 * m * 1.1 * d, 0.1, 0.05, t + 0.05 + i * 0.04));
    _sndClick(0.05, t);
  },
};

