    ctx.fillStyle = `rgba(255,160,0,0.7)`; ctx.fillRect(sx,sy+3+wave1,TILE,3);
    ctx.fillStyle = `rgba(255,220,0,0.5)`; ctx.fillRect(sx+2,sy+6+wave1,6,2);
