    ctx.beginPath(); ctx.moveTo(sx+10,sy); ctx.lineTo(sx+16,sy+10); ctx.lineTo(sx+10,sy+20); ctx.lineTo(sx+4,sy+10); ctx.closePath(); ctx.fill();
    ctx.globalAlpha=0.5;
    ctx.beginPath(); ctx.moveTo(sx+10,sy+20); ctx.lineTo(sx+16,sy+10); ctx.lineTo(sx+10,sy+20); ctx.lineTo(sx+4,sy+10); ctx.closePath();
    ctx.fillStyle='rgba(255,255,255,0.4)'; ctx.fill();
