    const gsHue = (x*53+y*37)%360;
    const gsGlow = 0.7+Math.sin(frameCount*0.1+x*2)*0.3;
    // Stalk
    ctx.fillStyle='rgba(180,100,220,0.8)'; ctx.fillRect(sx+8,sy+10,4,10);
    // Cap
