    ctx.fillStyle=`hsla(${gsHue},100%,80%,0.5)`;
    ctx.beginPath(); ctx.ellipse(sx+10,sy+9,5,3,0,0,Math.PI*2); ctx.fill();
    // Glow halo — hue is a per-tile constant hash (never animates), so it's
    // bucketed to the nearest 12° (30 stamps) and reused; alpha still breathes
