// Geometry for the one thing still drawn on top every frame — the eyes, so
// they can shift toward the direction of travel and blink independently of
// which body pose is showing. A character that never looks where it's going
// reads as a standing object being slid around, which is the single
// cheapest thing to fix about how a 2D character feels to control.
const PLAYER_EYE = { y: 11, colX: [7, 14], w: 3, h: 3, shift: 2 };

// Per-pixel texture noise (the "Minecraft" look): a flat fillRect per letter
// reads as a vector shape, not a material — real block textures never use
// one solid colour for "dirt" or "wood", every pixel sits a little lighter
// or darker than its neighbours. Each PIXEL gets its own small, PERMANENT
// brightness offset, so e.g. "shirt" stays one colour family but no two
// shirt pixels are quite identical. The offset is a pure function of the
// pixel's (row, col) rather than Math.random() — true randomness re-rolled
// on every bake would make each cached canvas different from the last with
// nothing driving it, and there'd be no way to reproduce a specific look.
// Hashing the coordinates instead makes the exact same pixel always land on
// the exact same offset. Kept in lockstep by hand with the identical
// functions in character-lab.html — that tool is where this design gets
// edited, this is only where it's shipped.
function _playerHashRC(row, col) {
  let h = Math.imul(row, 374761393) + Math.imul(col, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = (h ^ (h >>> 16)) >>> 0;
  return h / 4294967295;
}
const PLAYER_TEXTURE_NOISE = 16; // max +/- per RGB channel
function _playerHexToRgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function _playerRgbToHex(r, g, b) {
  const c = v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0');
  return '#' + c(r) + c(g) + c(b);
}
function _playerTextured(hex, row, col) {
  const [r, g, b] = _playerHexToRgb(hex);
  const n = (_playerHashRC(row, col) - 0.5) * 2 * PLAYER_TEXTURE_NOISE;
  return _playerRgbToHex(r + n, g + n, b + n);
}
// Skin (S) is player.color, an 'hsl(H,S%,L%)' string (see boot.js), not a
// fixed palette hex — jitter L directly rather than round-tripping hex/HSL.
function _playerTexturedSkin(cssColor, row, col) {
  const m = /^hsl\((\d+(?:\.\d+)?),\s*(\d+(?:\.\d+)?)%,\s*(\d+(?:\.\d+)?)%\)$/.exec(cssColor);
  if (!m) return cssColor; // not the expected format -- leave untouched rather than guess
  const [, h, s, l] = m.map(Number);
  const jitter = (_playerHashRC(row, col) - 0.5) * 2 * 6; // smaller range than cloth -- skin over-noised reads worse
  return `hsl(${h}, ${s}%, ${Math.max(0, Math.min(100, l + jitter))}%)`;
}

// player.color is randomised per session (see boot.js), and for a remote
// player it's whatever they broadcast — this is the game's whole "everyone
// looks a little different" identity mechanic (also drawn on their map ping,
// see drawPingMarker), not a cosmetic slot the player picks. One canvas is
// baked per (frame, colour) combination actually on screen — up to 5x more
// than the old single-sprite cache, but each is a small 24x56 canvas baked
// once and reused forever after, so even a multiplayer room with a dozen
// distinct hues stays trivial.
const _playerFrameCache = new Map();
function _getPlayerFrame(frameId, color) {
  const key = frameId + '|' + color;
  let cv = _playerFrameCache.get(key);
  if (cv) return cv;
  cv = document.createElement('canvas');
  cv.width = PLAYER_FRAME_W; cv.height = PLAYER_FRAME_H;
  const c = cv.getContext('2d');
  const g = PLAYER_FRAMES[frameId];
  for (let row = 0; row < g.length; row++) {
    const line = g[row];
    for (let col = 0; col < line.length; col++) {
      const ch = line[col];
      if (ch === '.') continue;
      c.fillStyle = (ch === 'S') ? _playerTexturedSkin(color, row, col) : _playerTextured(PLAYER_PALETTE[ch], row, col);
      c.fillRect(col, row, 1, 1);
    }
  }
  _playerFrameCache.set(key, cv);
  return cv;
}

