const VX_ICONS = {
  menu: drawIconMenu, book: drawIconBook, shield: drawIconShield,
  puzzle: drawIconPuzzle, palette: drawIconPalette, globe: drawIconGlobe,
  chat: drawIconChat, gear: drawIconGear, clover: drawIconClover,
  speaker: drawIconSpeaker, picture: drawIconPicture, gamepad: drawIconGamepad,
  note: drawIconNote, terrain: drawIconTerrain, bolt: drawIconBolt,
  bag: drawIconBag, upload: drawIconUpload, skull: drawIconSkull,
  stopwatch: drawIconStopwatch, star: drawIconStar, compass: drawIconCompass,
  link: drawIconLink, copy: drawIconCopy, ruler: drawIconRuler,
  pickaxe: drawIconPickaxe, rocket: drawIconRocket, diamond: drawIconDiamond,
  jumpup: drawIconJumpUp, speedlines: drawIconSpeedLines
};
// The one grid every icon ends up on. The drawIcon* functions above are not
// consistent about this — 21 of them author at 16px and 8 (menu, book, shield,
// puzzle, palette, globe, chat, gear) at 20px — and normalising here rather
// than rewriting their coordinates keeps each function's artwork exactly as
// drawn. It has to happen somewhere: `shield` is used at BOTH .vx-icon-menu and
// .vx-icon-sd, so no per-CSS-class size could ever have made every icon land
// 1:1 on its own buffer.
const VX_ICON_PX = 16;

// Resample an off-size icon down onto the shared grid. Smoothing is left ON
// for this step on purpose, even though the whole pass is about killing
// anti-aliasing: 20 -> 16 with nearest-neighbour would simply discard 4 of
// every 20 rows, deleting whole features (the middle bar of a hamburger, the
// pupil of an eye). Area-averaging preserves where the ink actually was, and
// _vxCrispen immediately below turns that grey back into hard pixels.
function _vxNormalize(cv) {
  if (cv.width === VX_ICON_PX && cv.height === VX_ICON_PX) return;
  const tmp = document.createElement('canvas');
  tmp.width = VX_ICON_PX; tmp.height = VX_ICON_PX;
  const t = tmp.getContext('2d');
  t.imageSmoothingEnabled = true;
  t.drawImage(cv, 0, 0, VX_ICON_PX, VX_ICON_PX);
  cv.width = VX_ICON_PX; cv.height = VX_ICON_PX;   // also clears the canvas
  cv.getContext('2d').drawImage(tmp, 0, 0);
}

// Runs once at load — these are all static HTML buttons (unlike the Portal
// Book's canvases, which redraw themselves every render), so a single pass
// over every canvas.vx-icon[data-icon] is all that's ever needed.
function _initVxIcons() {
  document.querySelectorAll('canvas.vx-icon[data-icon]').forEach(cv => {
    const fn = VX_ICONS[cv.dataset.icon];
    if (!fn) return;
    fn(cv);              // draw exactly as authored, at whatever size it wants
    _vxNormalize(cv);     // land it on the shared 16px grid
    _vxCrispen(cv);       // burn the anti-aliased edges to hard pixels
  });
}

// =========================================================
// CRAFTING — survival armor
// =========================================================
// Gives every dimension's materials a second purpose beyond "sell for coins":
// craft them into gear you actually need. Two parallel economies on purpose —
// soft currency (coins) drives account progression (upgrades/ranks), hard
// materials drive item power (armor) — which is the pattern most
// survival-sandbox games use because each covers a different need.
//
// ARMOR is a permanent, one-time craft per dimension. Owning a dimension's
// armor makes its passive hazards survivable (see isHazardProtected + the
// hazard checks in the game loop). It is deliberately a COMFORT tool, not a
// hard entry gate: the first trip into a new dimension is still risky (dash in,
// grab materials, retreat), then you gear up and explore for real — instead of
// an impossible "need lava gear to survive lava to get lava gear" deadlock.

// Dimensions that have a survival-armor set. OWNING (craftedArmor) is
// permanent once crafted — it never goes away, like a trophy. EQUIPPING
// (equippedArmor) is a separate, toggleable subset of what's owned: only
// equipped armor is drawn on the body and only equipped armor grants hazard
// protection, so taking a piece off is a real choice (you look different,
// and you lose that dimension's protection), not just a cosmetic no-op.
// Newly built armor auto-equips (see completeArmorAltar) since you'd want to wear
// what you just made — nothing is ever equipped that isn't also owned.
const ARMOR_DIMS = new Set(['GOLD', 'LAVA', 'OCEAN', 'VOID']);
let craftedArmor = new Set();          // dimension ids whose armor is owned forever (persisted)
let equippedArmor = new Set();         // dimension ids whose armor is currently worn (persisted, ⊆ craftedArmor)
// Frames of temporary hazard immunity — currently unreachable (nothing sets
// it above 0 since the Fireproof Draught consumable was removed), kept
// because isHazardProtected() below already reads it and the /aegis rank
// command (see AEGIS_DURATION) is documented to fill it too once built.
let hazardPotionTimer = 0;

// Each piece's own dimension hazard is still an outright bypass (see
// isHazardProtected() below), but that only ever mattered inside that one
// dimension. This is the RPG layer on top: every equipped piece ALSO chips
// away at a global damage multiplier that applies everywhere — mob bites,
// Overworld world-events, falls — so armor is worth wearing even when you're
// nowhere near the dimension it was made for. Multiplicative stacking (not
// flat subtraction) so no combination can ever round down to zero damage.
const ARMOR_DEFENSE = { GOLD: 0.15, LAVA: 0.15, OCEAN: 0.12, VOID: 0.12 };
const ARMOR_FULL_SET_BONUS = 0.10; // extra multiplicative cut for wearing all four at once
function armorDamageMultiplier() {
  let mult = 1;
  for (const dim of ARMOR_DIMS) if (equippedArmor.has(dim)) mult *= (1 - ARMOR_DEFENSE[dim]);
  if ([...ARMOR_DIMS].every(dim => equippedArmor.has(dim))) mult *= (1 - ARMOR_FULL_SET_BONUS);
  return mult;
}
// Small always-visible HUD readout (next to the hearts) of the total damage
// reduction your currently-equipped armor is granting. Hidden entirely while
// nothing is equipped so it doesn't clutter the HUD for new players.
function updateDefenseBadge() {
  const el = document.getElementById('defense-badge');
  if (!el) return;
  const pct = Math.round((1 - armorDamageMultiplier()) * 100);
  if (pct <= 0) { el.classList.remove('visible'); return; }
  const full = [...ARMOR_DIMS].every(dim => equippedArmor.has(dim));
  // The icon canvas is a permanent child (see the HTML), so this only ever
  // touches the text node after it — rebuilding with textContent would wipe
  // the icon the same way the old chat-unlock button used to.
  el.querySelector('.db-text').textContent = '-' + pct + '% DMG' + (full ? ' (Full Set)' : '');
  el.classList.add('visible');
}

// Re-derives the shared movement/mining stats (and max health) from the
// currently EQUIPPED armor. Only ever CLAMPS health down if maxHealth
// shrank (unequipping a piece), never heals up — otherwise toggling armor
// mid-fight would be a free heal button. Callers that want a full heal
// (world reset, cloud restore) explicitly set player.health after calling
// this.
function applyArmorStatBonuses() {
  let luck = 0, health = 0, speed = 0, jump = 0, reach = 0;
  for (const dim in ARMOR_STATS) {
    if (!equippedArmor.has(dim)) continue;
    const s = ARMOR_STATS[dim];
    if (s.luck) luck += s.luck;
    if (s.health) health += s.health;
    if (s.speed) speed += s.speed;
    if (s.jump) jump += s.jump;
  }
  if ([...ARMOR_DIMS].every(dim => equippedArmor.has(dim))) reach = ARMOR_FULL_SET_REACH_BONUS;
  maxReach = 5.0 + reach;
  playerSpeed = 3.5 + speed;
  jumpForce = -9 - jump;
  yieldMultiplier = 1 + luck;
  maxHealth = 12 + health;
  player.health = Math.min(player.health, maxHealth);
  drawHealth();
}

// Single source of truth for whether the player currently ignores dimension
// hazards: admin immunity, an active Fireproof Draught, or having that
// dimension's armor actually EQUIPPED right now (not merely owned). Replaces
// the old bare `!hasHazardImmunity` checks.
function isHazardProtected() {
  return hasHazardImmunity || hazardPotionTimer > 0 || equippedArmor.has(currentDim);
}

// Toggles a crafted armor piece between worn and stowed. No-op if you don't
// actually own it yet (equipping is only ever a display/protection choice
// over what's already been crafted, never a way to skip crafting).
function toggleArmorEquip(dim) {
  if (!craftedArmor.has(dim)) return;
  if (equippedArmor.has(dim)) {
    equippedArmor.delete(dim);
    showNotification('👕 Unequipped ' + dim + ' armor.');
  } else {
    equippedArmor.add(dim);
    showNotification('🛡️ Equipped ' + dim + ' armor.');
  }
  syncProgressToCloud();
  drawHotbar();
  updateDefenseBadge();
  applyArmorStatBonuses();
  // Armor state shows up on every level of the book (the "already built"
  // sub-line on a dimension tile, the equip button on the armor view), so
  // refresh whichever view happens to be open.
  if (document.getElementById('portal-book-modal').classList.contains('open')) renderPortalBook();
}

// recipe.mats: { blockId: amount, ... }. type 'armor' grants dimension armor
// (dim = the dimension it protects).
// EVERY armor now carries a `forge` field and is therefore never craftable from
// a button in this book — the Crafting tab shows it purely as information
// (the altar shape + its two materials + which realm builds it). Armor is only
// ever made in-world by placing the altar pattern (see ARMOR_PATTERN /
// checkArmorAltar / completeArmorAltar).
//
// SURVIVAL CHAIN (see FORGE_OUTPUT + DIM_CHAIN): the forge sits in the
// dimension BEFORE the one its armor protects, so you must forge each armor
// one dimension early to survive the next. forge.dim = where it's forged;
// dim = where it protects.
//   Gold forge  → Lava armor  (survive Lava)
//   Lava forge  → Ocean armor (survive Ocean)
//   Ocean forge → Void armor  (survive the Blither)
//   Void forge  → Gold armor  (bonus/prestige — Gold has no hazard of its own)
// Armor is never made from a menu — you BUILD it in the world. Place the two
// materials in the fixed 9-block altar shape (see ARMOR_PATTERN) while standing
// in the dimension named by `forge.dim`, and the blocks transform into the
// armor on the spot. `base` fills the 8 outer blocks, `core` is the single
// block in the middle row that the shape is anchored on. `mats` just mirrors
// those counts so the Portal Book can still show "do you carry enough".
const CRAFTING_RECIPES = [
  // ── Survival armor ──
  { id: 'armor_lava',  type: 'armor', dim: 'LAVA',
    name: 'Obsidian Heat Suit', effect: 'Built in the Gold Dimension from Obsidian with an Ember Ore core. Negates Lava Core heat & lava-contact damage.',
    base: BLOCKS.OBSIDIAN, core: BLOCKS.EMBER_ORE,
    mats: { [BLOCKS.OBSIDIAN]: 8, [BLOCKS.EMBER_ORE]: 1 },
    forge: { dim: 'GOLD', name: 'Vulcan-Schmiede' } },
  { id: 'armor_ocean', type: 'armor', dim: 'OCEAN',
    name: 'Pressure Diving Suit', effect: 'Built in the Lava Core from Ember Ore with a Fire Crystal core. Drastically slows Ocean Depth oxygen loss (not full immunity, you can still drown eventually).',
    base: BLOCKS.EMBER_ORE, core: BLOCKS.FIRE_CRYSTAL,
    mats: { [BLOCKS.EMBER_ORE]: 8, [BLOCKS.FIRE_CRYSTAL]: 1 },
    forge: { dim: 'LAVA', name: 'Flut-Altar' } },
  { id: 'armor_void',  type: 'armor', dim: 'VOID',
    name: 'Void Walker Boots', effect: 'Built in Ocean Depth from Coral with a Kelp core. Saves you from the deadly fall in the Blither.',
    base: BLOCKS.CORAL, core: BLOCKS.KELP,
    mats: { [BLOCKS.CORAL]: 8, [BLOCKS.KELP]: 1 },
    forge: { dim: 'OCEAN', name: 'Abgrund-Altar' } },
  { id: 'armor_gold',  type: 'armor', dim: 'GOLD',
    name: 'Golden Aegis', effect: 'Built in the Blither from Void Ore with a Star Dust core. Pure damage resistance, the prestige capstone of the chain.',
    base: BLOCKS.VOID_ORE, core: BLOCKS.STAR_DUST,
    mats: { [BLOCKS.VOID_ORE]: 8, [BLOCKS.STAR_DUST]: 1 },
    forge: { dim: 'VOID', name: 'Ur-Altar' } },
];

// The armor altar. 9 blocks, two materials, offsets relative to the CORE block:
//
//     B B B B B
//         C
//       B B B
//
// Deliberately nothing like the portal recipe's 5-block plus, so an ordinary
// wall — or a portal under construction — can never be mistaken for one.
const ARMOR_PATTERN = [
  [-2,-1],[-1,-1],[0,-1],[1,-1],[2,-1],   // top row, 5 wide
  [-1, 1],[0, 1],[1, 1]                    // bottom row, 3 wide
];

// ── Inventory helpers ──
function countInInventory(block) {
  let n = 0;
  for (const it of inventory) if (it && it.block === block) n += it.count;
  return n;
}
function recipeOwned(r) {
  return r.type === 'armor' && craftedArmor.has(r.dim);
}



function escapeHtml(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}


// Deferred to DOMContentLoaded rather than called inline here: this script
// runs partway through the body, but some icon-bearing elements (the age
// gate modal, deep in the COPPA/chat block) sit further DOWN the page and
// don't exist in the DOM yet at this point — querySelectorAll would just
// silently skip them. DOMContentLoaded guarantees the whole document,
// including everything below this line, has been parsed first.
window.addEventListener('DOMContentLoaded', _initVxIcons);

// The three piece designers are authored inside #game-wrapper next to the
// canvas, but they are also opened from the main menu (Creator Studio), which
// is a full-screen overlay. #game-wrapper is its own stacking context, so a
// child of it can never paint above that overlay no matter how high its
// z-index. Lifting them to <body> once at startup is the whole fix; their
// markup stays where it reads best, next to the rest of the game UI.
function _vxLiftDesignerModals() {
  for (const id of ['block-designer-modal', 'creature-designer-modal', 'mod-editor-modal', 'ng-blockpicker']) {
    const el = document.getElementById(id);
    if (el && el.parentElement !== document.body) document.body.appendChild(el);
  }
}
window.addEventListener('DOMContentLoaded', _vxLiftDesignerModals);

// ── Game Start (video intro removed — it was a 5MB+ inline base64 clip that
// blocked interaction behind a black overlay for up to 10s; cut for load time) ──
(function() {
  function announceMultiplayerStatus(attempt) {
    attempt = attempt || 0;
    if (isMultiplayerActive) {
      showNotification("🟢 Multiplayer is online!");
    } else if (attempt < 8) {
      setTimeout(function() { announceMultiplayerStatus(attempt + 1); }, 500);
    } else {
      showNotification("🔴 Multiplayer offline, playing solo");
    }
  }
  setTimeout(function() { announceMultiplayerStatus(0); }, 300);
  setTimeout(showIntroHintIfNeeded, 1500);
})();

// ── First-time intro hint — shown once ever per device, then never again ──
const INTRO_HINT_SEEN_KEY = 'voxeria_seen_intro_hint';
let introHintTimer = null;
function showIntroHintIfNeeded() {
  let seen = false;
  try { seen = localStorage.getItem(INTRO_HINT_SEEN_KEY) === '1'; } catch (e) {}
  if (seen) return;
  try { localStorage.setItem(INTRO_HINT_SEEN_KEY, '1'); } catch (e) {}
  const el = document.getElementById('intro-hint-banner');
  if (!el) return;
  el.classList.add('show');
  introHintTimer = setTimeout(dismissIntroHint, 10000);
}
function dismissIntroHint() {
  const el = document.getElementById('intro-hint-banner');
  if (el) el.classList.remove('show');
  if (introHintTimer) { clearTimeout(introHintTimer); introHintTimer = null; }
  // A queued contextual hint (see showHintOnce below) waiting for the banner
  // to free up — give the player a beat between hints instead of one banner
  // instantly replacing another.
  if (_hintQueue.length) setTimeout(_drainHintQueue, 600);
}
window.dismissIntroHint = dismissIntroHint;
// ─────────────────────────────────────────────────────────────────────────────

// ── Contextual one-time hints — same banner as the intro hint, reused for
// later milestones (first rank, first new dimension, first death) so a new
// player gets guidance spread across their first session instead of only a
// single tip at t=0. Each key fires at most once ever per device (localStorage-
// gated) and queues behind whichever hint is currently showing, if any.
const _hintQueue = [];
function showHintOnce(key, title, sub) {
  const storageKey = 'voxeria_hint_' + key;
  try { if (localStorage.getItem(storageKey) === '1') return; } catch (e) {}
  try { localStorage.setItem(storageKey, '1'); } catch (e) {}
  _hintQueue.push({ title, sub });
  const el = document.getElementById('intro-hint-banner');
  if (el && !el.classList.contains('show')) _drainHintQueue();
}
function _drainHintQueue() {
  const next = _hintQueue.shift();
  if (!next) return;
  const el = document.getElementById('intro-hint-banner');
  const titleEl = document.getElementById('ih-title');
  const subEl = document.getElementById('ih-sub');
  if (!el || !titleEl || !subEl) return;
  titleEl.textContent = next.title;
  subEl.textContent = next.sub;
  el.classList.add('show');
  introHintTimer = setTimeout(dismissIntroHint, 10000);
}

function _escH(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

